function splitName(name) {
  // 先頭の ＜…＞ や （…） を分類として分ける
  let rest = name.trim();
  const sub = [];
  let m;
  while ((m = rest.match(/^[＜（]([^＞）]+)[＞）]\s*/))) {
    sub.push(m[1]);
    rest = rest.slice(m[0].length);
  }
  return { main: rest, sub: sub.join('・'), parts: sub };
}

/* 成分表の名前を読みやすく：「こめ ［うるち米製品］ 焼きおにぎり」→「こめ 焼きおにぎり」（［］の中身は2行目へ）
   「そば そば 生」のように同じ言葉が続くときは1つに */
const DISP_DROP = new Set(['根', '果実', 'りん茎', '塊茎', '塊根', '球茎', '結球葉', '花序', '茎葉', '根茎', '若茎', '若ざや', '未熟種子', '子実体', '葉柄',
  'じょうのう', '軟白', '通年平均', '土耕栽培', '菌床栽培', '成魚']);
const DISP_KEEP_LEAF = new Set(['だいこん', 'かぶ', 'セロリ', 'さつまいも', 'すぐきな']); // 根と葉の両方を食べるもの：「葉」は残す
// ふだんの呼び方（種類の名前 → ふつうの名前。元の名前は2行目に）
const DISP_COMMON = { 'まさば': 'さば', 'まあじ': 'あじ', 'まいわし': 'いわし', 'しろさけ': 'さけ', 'くろまぐろ': 'まぐろ', 'するめいか': 'いか', 'まだこ': 'たこ',
  '青ピーマン': 'ピーマン', '赤色トマト': 'トマト', '赤色ミニトマト': 'ミニトマト', '西洋かぼちゃ': 'かぼちゃ', 'うんしゅうみかん': 'みかん', 'りょくとうもやし': 'もやし',
  '根深ねぎ': '長ねぎ', 'ぶなしめじ': 'しめじ', 'キウイフルーツ': 'キウイ', '日本なし': 'なし', 'スイートコーン': 'とうもろこし', 'まがれい': 'かれい', 'まだら': 'たら' };
const DISP_PHRASE = [['ぶどう酒 赤', '赤ワイン'], ['ぶどう酒 白', '白ワイン'], ['ぶどう酒 ロゼ', 'ロゼワイン'], ['清酒 ', '日本酒 '],
  ['しょうちゅう 連続式蒸留しょうちゅう', '焼酎（甲類）'], ['しょうちゅう 単式蒸留しょうちゅう', '焼酎（本格焼酎）'], ['まんじゅう 中華まんじゅう ', ''], ['いんげんまめ さやいんげん', 'さやいんげん'], ['しいたけ 生しいたけ', 'しいたけ'], ['かき 甘がき', 'かき']];
function dispName(name) {
  const notes = [];
  let n = String(name || '').replace(/［([^］]*)］|＜([^＞]*)＞/g, (_, a, b) => { notes.push(a || b); return ' '; });
  let words = n.split(/[\s　]+/).filter(Boolean).filter((w, i, arr) => w !== arr[i - 1]);
  const base = words[0];
  // 「根」「果実」などの部位、「通年平均」などの説明、最後の「生」は表示しない（ゆで・焼きなどは残す）
  words = words.filter((w, i) => i === 0 || !((DISP_DROP.has(w) && !(w === '根' && base === 'すぐきな')) || (w === '葉' && !DISP_KEEP_LEAF.has(base))));
  if (words.length > 1 && words[words.length - 1] === '生') words.pop();
  if (DISP_COMMON[words[0]]) { notes.unshift(words[0]); words[0] = DISP_COMMON[words[0]]; }
  n = words.join(' ');
  for (const [a, b] of DISP_PHRASE) if (n.startsWith(a)) n = b + n.slice(a.length);
  return { name: n || String(name || ''), note: notes.join('・') };
}


/* ---------- 必要量の計算 ---------- */
function bracketIndex(age) {
  return DRI.brackets.findIndex(([lo, hi]) => age >= lo && age <= hi);
}
function computeTargets(p) {
  if (!p || !p.age) return null;
  const age = Number(p.age);
  if (!(age >= 1)) return { unsupported: true };
  const i = bracketIndex(Math.floor(age));
  if (i < 0) return { unsupported: true };
  const sex = p.sex === 'f' ? 'f' : 'm';
  const add = sex === 'f' && ADD[p.status] ? ADD[p.status] : ADD.none;
  const rdaBase = DRI[sex].rda[i];
  const earBase = DRI[sex].ear[i];
  const w = Number(p.weight) || 0;
  const t = {
    bracket: DRI.brackets[i][2],
    sexLabel: sex === 'f' ? '女性' : '男性',
    rda: rdaBase + add.rda,
    ear: earBase + add.ear,
    addLabel: add.label,
    addRda: add.rda,
    goalPct: DRI.goal[i],
    weight: w || null,
    weightRef: null,
    frail: null,
    age,
  };
  if (age >= 18 && w > 0) {
    // 切上げ（食事摂取基準の丸め方に合わせる）
    t.weightRef = Math.ceil(w * ADULT_EAR_PER_KG * RDA_FACTOR) + add.rda;
  }
  // 高齢者の目安（1.2g/kg）。身長があれば標準体重（BMI22）を出し、
  // 太り気味（BMI25以上）や体重未入力のときは標準体重で計算する（多く出すぎないように）
  const h = Number(p.height) || 0;
  if (h > 0) {
    const hm = h / 100;
    t.stdWeight = Math.round(22 * hm * hm * 10) / 10;
    if (w > 0) t.bmi = Math.round(w / (hm * hm) * 10) / 10;
  }
  if (age >= 65) {
    let base = w, useStd = false;
    if (t.stdWeight && (!w || t.bmi >= 25)) { base = t.stdWeight; useStd = true; }
    if (base > 0) { t.frail = Math.ceil(base * FRAIL_PER_KG); t.frailBase = base; t.frailStd = useStd; }
  }
  // カロリーの目安（推定エネルギー必要量）。表に値がない活動量は「ふつう」で
  const act = ['low', 'mid', 'high'].includes(p.activity) ? p.activity : 'mid';
  const eerV = EER[sex][act][i] ?? EER[sex].mid[i];
  t.eer = eerV + (sex === 'f' ? EER.add[p.status] || 0 : 0);
  t.eerAct = EER[sex][act][i] != null ? act : 'mid';
  t.bmiGoal = bmiGoal(age);
  // 体重からの参考値も、太り気味なら標準体重で
  if (t.weightRef && t.stdWeight && t.bmi >= 25) { t.weightRef = Math.ceil(t.stdWeight * ADULT_EAR_PER_KG * RDA_FACTOR) + add.rda; t.weightRefStd = true; }
  return t;
}

/* ---------- 記録 ---------- */
function dayEntries(d) { return state.days[d] || []; }
function dayTotal(d) { return r1(dayEntries(d).reduce((a, e) => a + (Number(e.protein) || 0), 0)); }
function mealTotal(d, meal) { return r1(dayEntries(d).filter(e => e.meal === meal).reduce((a, e) => a + e.protein, 0)); }

function addEntry(d, entry) {
  if (!state.days[d]) state.days[d] = [];
  state.days[d].push(Object.assign({ id: uid() }, entry));
  if (entry.code) {
    const r = state.recent[entry.code] || { n: 0 };
    state.recent[entry.code] = Object.assign({}, r, { n: r.n + 1, g: entry.grams, t: Date.now() });
  }
  if (entry.mlId) {
    const k = 'ml:' + entry.mlId;
    const r = state.recent[k] || { n: 0 };
    state.recent[k] = { n: r.n + 1, t: Date.now() };
  }
  if (entry.refId) {
    const k = `${entry.kind}:${entry.refId}`;
    const r = state.recent[k] || { n: 0 };
    state.recent[k] = { n: r.n + 1, v: entry.basis === '100g' ? entry.grams : entry.qty, t: Date.now(), ...(entry.gu ? { gu: entry.gu, ga: entry.ga || {}, dashi: entry.dashi } : {}) };
  }
  saveState();
}
function updateEntry(d, id, patch) {
  const arr = dayEntries(d);
  const e = arr.find(x => x.id === id);
  if (e) Object.assign(e, patch);
  saveState();
}
function removeEntry(d, id) {
  state.days[d] = dayEntries(d).filter(x => x.id !== id);
  if (!state.days[d].length) delete state.days[d];
  saveState();
}
function proteinFor(food, grams) { return r1(food.p * grams / 100); }

/* ---------- 食品データの読込 ---------- */
async function loadFoods() {
  try {
    const res = await fetch('foods.json');
    const data = await res.json();
    foods = data.foods.map(([code, g, name, p, f, ml, rate, kcal, fat, carb]) => {
      const { main, sub, parts } = splitName(name);
      return { code, g, name, p, f, ml, rate: rate || null, kcal: kcal ?? null, fat: fat ?? null, carb: carb ?? null, main, sub, parts, group: data.groups[g], key: norm(name), kw: name.split(/\s+/).map(norm).filter(Boolean) };
    });
    foodByCode = new Map(foods.map(x => [x.code, x]));
    foodsReady = true;
    render();
  } catch (e) {
    toast('食品データを読み込めませんでした');
  }
}

/* ---------- 検索 ---------- */
function tokenize(q) {
  const raw = norm(q.replace(/[　]/g, ' ')).length ? q.normalize('NFKC').split(/\s+/).map(norm).filter(Boolean) : [];
  const out = [];
  for (const t of raw) {
    // 「鶏むね」のように言い換え語＋残りがくっついている場合は分割
    // 「さば缶」「ツナ缶」→「さば」「缶詰」
    if (t.length > 1 && t.endsWith('缶') && !NORM_ALIASES[t]) { out.push(t.slice(0, -1), norm('缶詰')); continue; }
    const k = NORM_ALIASES[t] ? null : ALIAS_KEYS.find(k => t.includes(k) && t !== k); // 言い換え語そのものは分割しない
    if (k) {
      out.push(k);
      t.split(k).filter(Boolean).forEach(x => out.push(x));
    } else out.push(t);
  }
  return out;
}
const STAPLE_CODES = new Set(STAPLES.map(s => s.code));
/* 並び順の考え方（小さいほど上）
   1. 最近使った食材（よく使う食材は少しだけ優先）
   2. 探した語が成分表の分類名（「（かつお類）」「（いか類）」など）に入っている → その仲間を優先
      ※「いか」で「すいか」、「たこ」で別の語が上に来るのを防ぐ
   3. 生（なま）を優先し、加工品・缶詰・干物・料理は下げる（探した語にその言葉が入っていれば下げない）
   4. 最後は名前の短い順 */
const PROCESSED_RE = /加工品|節|缶詰|佃煮|つくだ煮|塩辛|干し|干物|煮干|燻製|くん製|フレーク|味付け|調味|角煮|でんぶ|ふりかけ|すり身|練り|フライ|天ぷら|から揚げ|唐揚げ|料理|漬け|漬物|乾燥|粉末/;
function searchFoods(q) {
  const toks = tokenize(q);
  if (!toks.length) return [];
  const alts = toks.map(t => NORM_ALIASES[t] || [t]); // 言い換えがある語は言い換え先で探す（自分自身を含めたい語は ALIASES 側に書く）
  const res = [];
  for (const f of foods) {
    let ok = true;
    for (const a of alts) {
      // 語ごとに調べる（つなげると「…じか」＋「きゅうしゅう…」が「かき」に当たってしまうため）
      if (!a.some(x => f.kw.some(w => w.includes(x)))) { ok = false; break; }
    }
    if (ok) res.push(f);
  }
  const rec = state.recent;
  const nq = norm(q);
  const qProcessed = PROCESSED_RE.test(q) || PROCESSED_RE.test(nq);
  const score = f => {
    if (f._score != null && f._q === nq) return f._score;
    let sc = 0;
    // よく使う食材は少しだけ上に（生と加工品の並びは崩さない）。最近自分で記録したものはしっかり上に
    if (STAPLE_CODES.has(f.code)) sc -= 20;
    if (rec[f.code]) sc -= 25;
    const parts = f.parts || []; // 分類名（「いか・たこ類」「たこ類」など、名前の区切りどおり）
    const cat = norm((f.sub || '') + ((f.main || '').match(/［([^］]*)］/) || [])[1] || '');
    const last = norm(parts[parts.length - 1] || ''); // いちばん細かい分類（例：「たこ類」）
    const main = norm(f.main || '');
    const hit = x => x.replace(/類?\)$/, ''); // 「かつお類)」→「かつお」
    // 分類名に探した語が入っている（その仲間）。細かい分類に入っていればさらに上
    // 「たこ」→「（たこ類）」のように分類名がその語そのものなら強く、「（菓子パン類）」のように一部に含むだけなら弱く
    const catWords = parts.map(norm);
    const catHit = alts.some(a => a.some(x => catWords.includes(hit(x) + '類') || last === hit(x) || (f.code.startsWith('18') && main.includes(hit(x) + '類'))));
    if (catHit) sc -= 30;
    else if (alts.some(a => a.some(x => cat.includes(hit(x))))) sc -= 10;
    // 食品名が探した語で始まる（例：「かつお 春獲り 生」）
    if (alts.some(a => a.some(x => main.startsWith(hit(x))))) sc -= 8;
    // 食品名に探した語が入っている。1個・1切れなどの目安があるもの（ふだん食べる形）はさらに少し上に
    // 分類の部分（［うどん・そうめん類］など）を除いた、食品そのものの名前
    const core = norm((f.main || '').replace(/［[^］]*］|＜[^＞]*＞|（[^）]*類）/g, ''));
    const nameHit = alts.some(a => a.some(x => core.includes(hit(x))));
    if (nameHit) sc -= 15;
    if ((nameHit || catHit) && FOOD_UNITS[f.code]) sc -= 8;
    // 食品名の最後の語がそのもの（例：「中国料理 点心類 ぎょうざ」）なら料理でも上に
    const lastWord = norm((f.main || '').split(/\s+/).pop() || '');
    if (f.code.startsWith('18') && alts.length === 1 && alts[0].some(x => lastWord === hit(x))) sc -= 25;
    // 生を優先
    if (/(^|\s)生(\s|$)/.test(f.main || '')) sc -= 6;
    // 加工品・料理は下げる
    if (!qProcessed && (PROCESSED_RE.test((f.main || '').replace('水産練り製品', '')) || PROCESSED_RE.test((f.sub || '').replace('水産練り製品', '')))) sc += 20;
    // 「ぎょうざの皮」などの材料は、皮と探したとき以外は下げる
    if (/の皮/.test(f.main || '') && !/皮/.test(q)) sc += 15;
    // 「ちくわ」で「ちくわぶ」（小麦製品）が先に出ないように
    if (/ちくわぶ/.test(f.main || '') && !/ぶ|麩/.test(q)) sc += 15;
    if (/コーンフレーク/.test(f.main || '') && !/コーン|シリアル/.test(q)) sc += 30; // 「ツナ」（フレーク）で出ないように
    // 皮だけの食品（「あひる 皮」など）は、皮と探したとき以外は少し下げる
    if (/(^|\s)皮(\s|$)/.test(f.main || '') && !/皮/.test(q)) sc += 8;
    f._q = nq; f._score = sc;
    return sc;
  };
  res.sort((a, b) => (score(a) - score(b)) || (a.name.length - b.name.length));
  return res.slice(0, 60);
}

/* =========================================================
   描画
   ========================================================= */
function render() {
  $('#datenav').hidden = currentTab !== 'today';
  $('#dateLabel').textContent = dateLabel(viewDate);
  $('#todayBtn').hidden = viewDate === todayStr();
  const past = viewDate !== todayStr();
  document.body.classList.toggle('not-today', past);
  document.documentElement.classList.toggle('not-today', past);
  $('#pastBar').hidden = !past || currentTab !== 'today';
  $('#pastBarText').textContent = dateLabel(viewDate) + ' の記録を見ています';
  const tc = document.querySelector('meta[name="theme-color"]'); if (tc) tc.content = past ? '#fffdf8' : '#f4fbfd';
  if (currentTab === 'today') renderToday();
  if (currentTab === 'history') renderHistory();
  if (currentTab === 'settings') renderSettings();
  playPendingHop();
}

// めだかの筋肉段階：〜50%=1／〜85%=2／〜100%=3／達成=4
function stageOf(r) { return r < 0.5 ? 1 : r < 0.85 ? 2 : r < 1 ? 3 : 4; }

function ringSvg(ratio) {
  // 水位で見せる：丸い水槽にたんぱく質の量だけ水がたまる。届くと満水（金の縁）
  const v = Math.max(0, Math.min(1, ratio));
  const y = v >= 1 ? -8 : 124 - 116 * v;
  const wave = (c) => `<path d="M0 6 Q16.5 0 33 6 T66 6 T99 6 T132 6 T165 6 T198 6 T231 6 T264 6 V140 H0Z" fill="${c}"/>`;
  // たんぱく質がたまるほど、水の中のめだかが増える（届くと4匹）
  const spots = [[0.3, 74, 93, 30], [0.45, 22, 99, 26], [0.6, 48, 106, 22], [1, 86, 104, 20]];
  const fish = spots.filter(s => v >= s[0]).map((s, i) =>
    `<image class="fishy" style="animation-delay:-${i * 0.9}s" href="characters/medaka-m${stageOf(ratio)}.png" x="${s[1]}" y="${s[2]}" width="${s[3]}" height="${(s[3] * 0.8).toFixed(1)}"/>`).join('');
  return `<svg viewBox="0 0 132 132" aria-hidden="true">
    <defs><clipPath id="pnClip"><circle cx="66" cy="66" r="59"/></clipPath></defs>
    <circle cx="66" cy="66" r="59" fill="var(--track)" opacity=".45"/>
    <g clip-path="url(#pnClip)">
      <g transform="translate(0,${(y - 3).toFixed(1)})"><g class="wv2">${wave('var(--w2)')}</g></g>
      <g transform="translate(0,${y.toFixed(1)})"><g class="wv">${wave('var(--w1)')}</g></g>
      ${fish}
    </g>
    <circle cx="66" cy="66" r="62" fill="none" stroke="${ratio >= 1 ? 'var(--gold)' : 'var(--primary)'}" stroke-width="5"/>
  </svg>`;
}

// めだかのひとこと（1画面に1つ）

function playPendingHop() {
  if (!hitokoto.pending || !$('#sheet').hidden || currentTab !== 'today') return;
  hitokoto.pending = false;
  setTimeout(() => hopMedaka($('.hop img')), 350);
}
function hitokoto(ratio) {
  const past = viewDate !== todayStr();
  const md = viewDate.split('-');
  const day = `${Number(md[1])}月${Number(md[2])}日`;
  let m;
  const st = ratio <= 0 ? 1 : stageOf(ratio);
  if (past) {
    if (ratio <= 0) m = `${day}の記録だよ。`;
    else if (ratio < 0.5) m = `${day}の記録だよ。もう一歩だったね。`;
    else if (ratio < 0.85) m = `${day}の記録だよ。いい調子だったね！`;
    else if (ratio < 1) m = `${day}の記録だよ。もう少しだったね！`;
    else m = `${day}は達成していたよ！おつかれさま！`;
  }
  else if (ratio <= 0) m = '今日もよろしくね。';
  else if (ratio < 0.5) m = 'まずは一歩。いいね！';
  else if (ratio < 0.85) m = 'いい調子！！';
  else if (ratio < 1) m = 'もう少し！';
  else m = '達成！！おつかれさま！';
  // 段階が上がった（めだかがマッチョになった）ら、一度だけ跳ねて見せる
  // 達成したあとは、さらに記録してたんぱく質が増えるたびに跳ねて見せる
  if (!past) {
    const seen = hitokoto.seen[viewDate];
    if (seen && (st > seen.st || (st === 4 && ratio > seen.r + 1e-9))) hitokoto.pending = true;
    hitokoto.seen[viewDate] = { st, r: ratio };
  }
  return `<div class="hito hito-m${st}"><button class="hop" data-hop="1" aria-label="めだか"><img src="characters/medaka-m${st}.png" alt=""></button><span>${m}</span></div>`;
}
hitokoto.seen = {};

/* ---------- 更新のお知らせ（大きな更新のときだけ） ----------
   新しいお知らせを先頭に足す。banner は今日の画面の上に出す1行（一度閉じたら出ない）。items は設定の「更新のお知らせ」に並べる。
   go：「見てみる」で開くタブ（settings なら表示の欄へ） */
const NEWS = [
  { id: '2026-11-nutri', date: '2026年11月', banner: '更新！！ほかの栄養素も見られるようになったよ！ 見たい人は設定画面から表示をオンにしてね！', go: 'settings',
    items: ['食塩・食物繊維・カルシウム・鉄・ビタミンも見られるようになりました（設定の「表示」でオンにした人だけ）',
      '鍋・みそ汁・焼肉・すき焼き・カレーで、具の量を直せるようになりました。鍋は味（だし・たれ）も選べます',
      '料理もマイリストに入れられるようになりました（☆ この内容でマイリストへ）',
      '市販品は「Webで調べる」と「栄養成分表示を貼り付け」で、かんたんに登録できます',
      '魚の名前で探すと刺身も出るようになりました。KFCのメニューを最新にしました'] },
];
function newsBanner() {
  const n = NEWS[0];
  if (!n || currentTab !== 'today' || state.newsSeen === n.id) return '';
  return `<div class="news-band" role="status"><span class="news-text">${esc(n.banner)}</span>
    <span class="news-acts"><button class="btn small" data-newsgo="1">見てみる</button><button class="news-x" data-newsx="1" aria-label="お知らせを閉じる">✕</button></span></div>`;
}
function markNewsSeen() { if (NEWS[0]) { state.newsSeen = NEWS[0].id; saveState(); } }
function newsCard() {
  if (!NEWS.length) return '';
  return `<div class="card" id="newsCard"><h2>更新のお知らせ</h2>${NEWS.map(n => `<div class="news-item"><div class="small" style="font-weight:700">${esc(n.date)}</div><ul class="small">${n.items.map(x => `<li>${esc(x)}</li>`).join('')}</ul></div>`).join('')}</div>`;
}

function renderToday() {
  const el = $('#tab-today');
  const t = computeTargets(state.profile);
  const total = dayTotal(viewDate);
  let html = newsBanner();
  let suggestHtml = '';

  if (!t) {
    html += `<div class="card welcome">
      <h2>はじめに</h2>
      <p>年齢と性別を入れると、1日に必要なたんぱく質の量（推奨量）を表示します。</p>
      <p><button class="btn ghost small" style="background:#fff" data-go="settings">年齢・性別を入れる</button></p>
    </div>`;
  } else if (t.unsupported) {
    html += `<div class="card"><p>このツールは1歳以上が対象です。乳児の目安量は「設定・出典」を参照してください。</p></div>`;
  }

  // サマリー
  if (t && !t.unsupported) {
    const target = t.rda;
    const remain = r1(target - total);
    let rows = `<div class="target-row main"><span>推奨量<span class="tiny muted">（${t.bracket}${t.sexLabel}${t.addLabel ? '・' + t.addLabel : ''}）</span></span><b>${target}g</b></div>`;
    if (t.frail) rows += `<div class="target-row frail"><span>＋高齢者の目安<span class="tiny muted">（1.2g/kg${t.frailStd ? '・標準体重' : ''}）</span></span><b>${t.frail}g</b></div>`;
    if (t.age >= 65 && !t.frail) rows += `<div class="target-row"><span class="small muted">体重か身長を入れると、高齢者の目安（フレイル予防）も表示します</span></div>`;

    const maxV = Math.max(target, t.frail || 0, total) * 1.08 || 1;
    let marks = '';
    if (t.frail && t.frail !== target) marks += `<div class="mark" style="left:${(t.frail / maxV) * 100}%"><span>${t.frail}g</span></div>`;
    marks += `<div class="mark" style="left:${(target / maxV) * 100}%;background:var(--primary)"><span style="color:var(--primary)">${target}g</span></div>`;

    html += `<div class="card">
      <div class="summary">
        <div class="ring">${ringSvg(total / target)}
          <div class="center"><div class="big">${fmt(total)}</div><div class="unit">g / ${target}g</div></div>
        </div>
        <div class="targets">${rows}</div>
      </div>
      <div class="bar"><div class="fill" style="width:${(total / maxV) * 100}%"></div>${marks}</div>
      <div style="height:14px"></div>
      ${hitokoto(total / target)}
      ${remain > 0
        ? `<div class="remain">推奨量まで あと <span style="color:var(--accent)">${fmt(remain)}g</span></div>`
        : `<div class="remain done">推奨量に届きました（+${fmt(-remain)}g）</div>`}
      ${t.frail && total >= target && total < t.frail ? `<div class="small muted">高齢者の目安（${t.frail}g）まで あと ${fmt(t.frail - total)}g</div>` : ''}
      ${showNut() && foodsReady ? pfcHtml(dayEntries(viewDate), t) : ''}
      ${showNutri() && foodsReady ? nutriTodayHtml(dayEntries(viewDate)) : ''}
    </div>`;

    if (remain > 0 && foodsReady) suggestHtml = renderSuggestions(remain);
  }

  // 写真
  html += `<div class="photo-bar">
    <button class="btn ghost small" id="photoAddBtn" aria-label="食べたものの写真を入れる">📷 写真</button>
    <span class="tiny muted">撮った日時で朝・昼・夕・間食に振り分けます</span>
  </div>`;

  // 食事
  for (const [m, label] of MEALS) {
    const list = dayEntries(viewDate).filter(e => e.meal === m);
    html += `<div class="card">
      <div class="meal-head"><h2>${label}</h2><span class="meal-total">${showNut() && list.length && foodsReady ? (n => n.unknown === list.length ? '' : `<span class="tiny muted" style="font-weight:400">${n.kcal}kcal${n.unknown ? '＋不明' : ''}　</span>`)(sumNut(list)) : ''}${fmt(mealTotal(viewDate, m))}g</span></div>
      <div class="pstrip" data-pmeal="${m}"></div>
      ${list.map(e => `<button class="entry" data-edit="${e.id}">
          <span class="nm"><div>${esc(dispName(e.name).name)}</div><div class="tiny muted">${esc(entryAmountLabel(e))}${showNut() && foodsReady ? (n => n.kcal == null ? '・kcal不明' : `・${n.kcal}kcal`)(entryNut(e)) : ''}</div></span>
          <span class="pg">${fmt(e.protein)}g</span>
        </button>`).join('')}
      <div class="meal-actions">
        <button class="btn small" data-add="${m}">＋ 追加</button>
        <button class="btn ghost small" data-copy="${m}">前日と同じ</button>
      </div>
    </div>`;
  }
  html += suggestHtml; // 記録のあとに「あとなんgをとるなら」
  html += `<p class="tiny muted" style="text-align:center">食品の値：日本食品標準成分表（八訂）増補2023年から引用</p>`;
  el.innerHTML = html;
  fillPhotoStrips();
}

function renderSuggestions(remain) {
  const items = SUGGEST_CODES.map(c => {
    const f = foodByCode.get(c);
    const st = STAPLES.find(x => x.code === c);
    const u = unitsFor(f)[0];
    if (!f || !st || !u) {
      if (!f || !st) return null;
      // 目安量がない食品は100gで
      const per = proteinFor(f, 100);
      return { f, label: st.label, uLabel: '100g', g: 100, per, need: `約${Math.ceil((remain / f.p) * 100 / 10) * 10}g` };
    }
    const per = proteinFor(f, u.g);
    const need = u.c ? `約${fmt(Math.ceil((remain / per) * 2) / 2)}${u.c}` : `約${Math.ceil((remain / f.p) * 100 / 10) * 10}g`;
    return { f, label: st.label, uLabel: u.l, g: u.g, per, need };
  }).filter(Boolean);
  return `<div class="card">
    <h2>あと${fmt(remain)}gをとるなら</h2>
    <div class="sugg">
      ${items.map(x => `<button data-quick="${x.f.code}">
        <b>${esc(x.label)}</b>
        ${esc(x.uLabel)}で${fmt(x.per)}g<br><span class="muted">→ ${x.need}分</span>
      </button>`).join('')}
    </div>
    <div class="tiny muted" style="margin-top:6px">どれか1つでとる場合の量です。タップで記録できます。</div>
  </div>`;
}

function renderHistory() {
  const el = $('#tab-history');
  const t = computeTargets(state.profile);
  const target = t && !t.unsupported ? t.rda : null;
  const days = [];
  for (let i = 13; i >= 0; i--) days.push(addDays(todayStr(), -i));
  const vals = days.map(d => ({ d, v: dayTotal(d), has: dayEntries(d).length > 0 }));
  const maxV = Math.max(target || 0, ...vals.map(x => x.v), 10) * 1.1;
  const recorded = vals.filter(x => x.has);
  const avg = recorded.length ? recorded.reduce((a, x) => a + x.v, 0) / recorded.length : 0;
  const ok = target ? recorded.filter(x => x.v >= target).length : 0;

  let html = `<div class="card">
    <h2>直近14日</h2>
    <div class="chart">
      ${target ? `<div class="tline" style="bottom:${(target / maxV) * 100}%"><span>推奨量 ${target}g</span></div>` : ''}
      ${vals.map(x => `<button class="col" data-day="${x.d}" aria-label="${x.d} ${fmt(x.v)}g">
          <div class="b ${target && x.v >= target ? 'ok' : ''} ${x.d === todayStr() ? 'today' : ''}" style="height:${(x.v / maxV) * 100}%"></div>
        </button>`).join('')}
    </div>
    <div class="chart-days">${vals.map(x => `<span>${parseDate(x.d).getDate()}</span>`).join('')}</div>
    <div class="tiny muted">棒をタップするとその日の記録を開きます</div>
  </div>
  <div class="card">
    <div class="stats">
      <div><b>${recorded.length}</b><span class="tiny muted">記録した日</span></div>
      <div><b>${fmt(avg)}g</b><span class="tiny muted">平均（記録日）</span></div>
      <div><b>${target ? ok : '-'}</b><span class="tiny muted">推奨量に届いた日</span></div>
    </div>
  </div>`;

  if (showNutri() && foodsReady) html += `<div class="card"><h2>ほかの栄養素</h2><p class="small muted" style="margin-top:0">食塩・食物繊維・カルシウム・鉄・ビタミンを、直近7日の平均で基準の値と比べます</p><button class="btn ghost small block" data-nutri="week">直近7日の平均を見る</button></div>`;
  html += weightCard();

  const allDays = Object.keys(state.days).sort().reverse().slice(0, 60);
  html += `<div class="card daylist"><h2>記録一覧</h2>
    ${allDays.length ? allDays.map(d => `<button class="row" data-day="${d}"><span>${dateLabel(d)}</span><b>${fmt(dayTotal(d))}g</b></button>`).join('') : '<div class="empty">まだ記録がありません</div>'}
  </div>`;
  el.innerHTML = html;
}

/* ---------- 体重メモ（食事摂取基準：カロリーの過不足は体重の変化で見る） ---------- */
function weightCard() {
  const ws = (state.weights || []).slice().sort((a, b) => a.d < b.d ? -1 : 1);
  const h = Number(state.profile && state.profile.height) || 0;
  const bmiOf = kg => h ? r1(kg / ((h / 100) ** 2)) : null;
  const last = ws[ws.length - 1];
  const pre = (last && last.d === todayStr() ? last.kg : null) ?? (state.profile && state.profile.weight) ?? '';
  let spark = '';
  const pts = ws.slice(-12);
  if (pts.length >= 2) {
    const lo = Math.min(...pts.map(x => x.kg)), hi = Math.max(...pts.map(x => x.kg));
    const rng = Math.max(hi - lo, 1);
    const xy = pts.map((x, i) => [8 + i * (284 / (pts.length - 1)), 8 + (1 - (x.kg - lo) / rng) * 44]);
    spark = `<svg viewBox="0 0 300 60" style="width:100%;height:60px;display:block;margin:6px 0">
      <polyline points="${xy.map(a => a.join(',')).join(' ')}" fill="none" stroke="var(--primary)" stroke-width="2.5" stroke-linejoin="round"/>
      ${xy.map(a => `<circle cx="${a[0]}" cy="${a[1]}" r="3.5" fill="var(--primary)"/>`).join('')}</svg>`;
  }
  const rows = ws.slice(-8).reverse().map((x, i, arr) => {
    const prev = arr[i + 1];
    const diff = prev ? r1(x.kg - prev.kg) : null;
    return `<button class="row" data-wdel="${x.d}"><span>${dateLabel(x.d)}</span><b>${fmt(x.kg)}kg<span class="tiny muted" style="font-weight:400">${diff != null ? `（${diff > 0 ? '+' : ''}${fmt(diff)}）` : ''}${bmiOf(x.kg) ? `・BMI ${fmt(bmiOf(x.kg))}` : ''}</span></b></button>`;
  }).join('');
  return `<div class="card daylist">
    <h2>体重</h2>
    <div class="amount-box" style="margin-top:4px"><input id="wInput" type="number" inputmode="decimal" step="0.1" min="10" max="250" value="${esc(pre)}" placeholder="例：55.0"><span class="u">kg</span>
      <button class="btn small" id="wSave" style="flex:none">きょうの体重を記録</button></div>
    ${spark}
    ${rows || '<div class="empty small">週に1回くらい記録すると、増えているか減っているかがわかります</div>'}
    <div class="tiny muted" style="margin-top:6px">食べた量が足りているかは、体重の変化で見るのが確実です（食事摂取基準）。記録すると「設定」の体重も書きかわります。行をタップすると削除できます。</div>
  </div>`;
}
function saveWeight() {
  const kg = Number($('#wInput').value);
  if (!(kg > 0)) { toast('体重を入れてください'); return; }
  const age = Number(state.profile && state.profile.age) || 0;
  if ((age && kg === age) || (age >= 18 && kg < 30)) {
    if (!confirm(`${kg}kgで記録します。体重（kg）で合っていますか？`)) return;
  }
  state.weights = (state.weights || []).filter(x => x.d !== todayStr());
  state.weights.push({ d: todayStr(), kg: r1(kg) });
  if (state.profile) state.profile.weight = r1(kg);
  saveState();
  toast(`${fmt(kg)}kg を記録しました`);
  render();
}

function renderSettings() {
  const el = $('#tab-settings');
  photoCount().then(n => { const x = $('#photoCountLabel'); if (x) x.textContent = `保存中の写真：${n}枚`; });
  const p = state.profile || {};
  const t = computeTargets(state.profile);
  el.innerHTML = `
  <div class="card">
    <h2>あなたの情報</h2>
    <form id="profileForm">
      <div class="field"><label for="age">年齢（歳）</label>
        <div style="display:flex;align-items:center;gap:8px"><input id="age" name="age" type="number" inputmode="numeric" min="1" max="120" value="${esc(p.age || '')}" placeholder="例：45" required><b style="flex:none">歳</b></div></div>
      <div class="field"><label>性別</label>
        <div class="radio-row">
          <label><input type="radio" name="sex" value="m" ${p.sex === 'm' ? 'checked' : ''} required>男性</label>
          <label><input type="radio" name="sex" value="f" ${p.sex === 'f' ? 'checked' : ''}>女性</label>
        </div></div>
      <div class="field"><label for="height">身長（cm・任意）</label>
        <div style="display:flex;align-items:center;gap:8px"><input id="height" name="height" type="number" inputmode="decimal" step="0.1" min="80" max="230" value="${esc(p.height || '')}" placeholder="例：155"><b style="flex:none">cm</b></div></div>
      <div class="field"><label for="weight">体重（kg・任意）</label>
        <div style="display:flex;align-items:center;gap:8px"><input id="weight" name="weight" type="number" inputmode="decimal" step="0.1" min="10" max="250" value="${esc(p.weight || '')}" placeholder="例：55"><b style="flex:none">kg</b></div>
        <div id="weightWarn" class="hint" style="color:#c0392b;font-weight:700" hidden></div>
        <div class="hint">65歳以上は、推奨量に加えて「高齢者の目安（1.2g/kg）」も表示します。身長も入れると、太り気味のときは標準体重で計算します</div></div>
      <div class="field" id="statusField" ${p.sex === 'f' ? '' : 'hidden'}><label for="status">妊娠・授乳</label>
        <select id="status" name="status">
          ${Object.entries(ADD).map(([k, v]) => `<option value="${k}" ${p.status === k ? 'selected' : ''}>${k === 'none' ? '該当しない' : v.label}</option>`).join('')}
        </select></div>
      <div class="field"><label for="activity">ふだんの活動量</label>
        <select id="activity" name="activity">
          ${ACTIVITY.map(([k, l, d]) => `<option value="${k}" ${(p.activity || 'mid') === k ? 'selected' : ''}>${l}（${d}）</option>`).join('')}
        </select>
        <div class="hint">カロリーの目安を出すときに使います（75歳以上と子どもは「高い」の値がないため「ふつう」で計算）</div></div>
      <button class="btn block" type="submit">保存</button>
    </form>
  </div>

  ${t && !t.unsupported ? `<div class="card">
    <h2>あなたの目安</h2>
    <div class="target-row main"><span>推奨量</span><b>${t.rda}g/日</b></div>
    <div class="target-row"><span>推定平均必要量</span><b>${t.ear}g/日</b></div>
    ${t.weightRef ? `<div class="target-row"><span>体重からの参考値${t.weightRefStd ? '（標準体重' + fmt(t.stdWeight) + 'kg）' : ''}</span><b>${t.weightRef}g/日</b></div>` : ''}
    ${t.frail ? `<div class="target-row frail"><span>＋高齢者の目安（フレイル予防・1.2g/kg${t.frailStd ? '・標準体重' + fmt(t.frailBase) + 'kg' : ''}）</span><b>${t.frail}g/日</b></div>` : ''}
    <div class="target-row"><span>目標量（参考）</span><b>${t.goalPct}%エネルギー</b></div>
    ${t.bmiGoal && t.bmi ? `<div class="target-row"><span>BMI<span class="tiny muted">（目標とする範囲 ${fmt(t.bmiGoal[0])}〜${fmt(t.bmiGoal[1])}）</span></span><b>${fmt(t.bmi)}</b></div>` : ''}
    <div class="target-row"><span>カロリーの目安<span class="tiny muted">（活動量「${ACTIVITY.find(a => a[0] === t.eerAct)[1]}」）</span></span><b>約${t.eer.toLocaleString()}kcal/日</b></div>
    <p class="small muted" style="margin-bottom:0">
      <b>推奨量</b>：ほとんどの人（97〜98%）が不足しない量。${t.bracket}・${t.sexLabel}の表の値${t.addRda ? `に${t.addLabel}の付加量 +${t.addRda}g を加えた値` : ''}です。<br>
      <b>推定平均必要量</b>：半数の人が必要量を満たす量。<br>
      ${t.weightRef ? `<b>体重からの参考値</b>：成人の推奨量の計算式（0.73g/kg × 1.25）をあなたの体重に当てはめた値です。表の値は「参照体重」で計算されています。<br>` : ''}
      ${t.frail ? `<b>高齢者の目安</b>：食事摂取基準では、高齢者は推奨量より多め（1.2g/kg体重/日以上）にとるとフレイル・サルコペニアを予防できる可能性がある、とされています（確定した基準値ではありません）。基本は推奨量で、余裕があればここまで、という目安です。${t.frailStd ? '太り気味（BMI25以上）のため、実際の体重ではなく身長から出した標準体重（BMI22）で計算しています。' : ''}腎臓の病気などで食事の指導を受けている方は、医師の指示を優先してください。<br>` : ''}
      <b>目標量</b>：生活習慣病などの予防のため、1日のエネルギーのうちたんぱく質でとる割合です。上限の20%は、それを超えると高齢者では腎臓に良くない影響があるかもしれない、として決められています（はっきりした根拠はまだありません）。<br>
      ${t.bmiGoal ? `<b>BMI</b>：体重(kg)÷身長(m)÷身長(m)。食事摂取基準は、カロリーのとりすぎ・不足を、食べた量ではなく体重の変化とBMIで見るように、としています。目標とする範囲は年代ごとの値です。${t.age >= 65 ? '高齢の方は、やせや栄養不足のほうにも注意が必要とされています。' : ''}${t.bmi ? '' : '身長と体重を入れると表示します。'}<br>` : ''}
      <b>カロリーの目安</b>：食事摂取基準の「推定エネルギー必要量」（年齢・性別・活動量ごとの平均的な値）です。体格の違いは入っていないので、一人ひとりには誤差があります。足りているかどうかは、体重が増えたり減ったりしていないかで見てください。
    </p>
  </div>` : ''}

  <div class="card">
    <h2>マイリスト</h2>
    <p class="small muted" style="margin-top:0">よく食べるものを入れておくと、追加画面からタップ1回で記録できます。料理（鍋なら具や味も）・食材は「メニューを登録」から探すか、記録するときの「☆ マイリストへ」で。市販品はパッケージの表示から登録します。</p>
    ${state.myList.length ? mlSorted().map(it => `<button class="entry" data-mledit="${it.id}">
      <span class="nm"><div>${esc(it.name)}</div><div class="tiny muted">${esc(mlAmountLabel(it))}・${ML_KIND_LABEL[it.kind]}</div></span><span class="pg">${foodsReady || it.kind === 'prod' || it.kind === 'menu' ? fmt(mlProteinShown(it)) + 'g' : ''}</span></button>`).join('') : '<div class="empty small">まだありません</div>'}
    <div class="meal-actions" style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn small" id="mlRegMenu">＋ メニューを登録</button><button class="btn ghost small" data-mlnew="1">＋ 市販品を登録</button></div>
  </div>

  <div class="card" id="dispCard">
    <h2>表示</h2>
    <label style="display:flex;gap:10px;align-items:center;font-weight:700"><input type="checkbox" id="showPFC" ${state.showPFC ? 'checked' : ''} style="width:22px;height:22px">カロリー・PFC（脂質・炭水化物）も表示する</label>
    <div class="hint" style="margin-top:6px">オンにすると、今日の画面に1日の合計kcalとPFCの割合、記録ごとのkcalを小さく表示します。料理（目安）のカロリーは油の量などでぶれる、おおまかな値です。</div>
    <label style="display:flex;gap:10px;align-items:center;font-weight:700;margin-top:14px"><input type="checkbox" id="showNutri" ${state.showNutri ? 'checked' : ''} style="width:22px;height:22px">ほかの栄養素（食塩・食物繊維・カルシウム・鉄・ビタミン）も表示する</label>
    <div class="hint" style="margin-top:6px">オンにすると、今日の画面に食塩・食物繊維・カルシウム・鉄を、「詳細」でビタミンも表示します。食品成分表から計算した大まかな目安です。</div>
  </div>

  <div class="card">
    <h2>写真</h2>
    <p class="small muted" style="margin-top:0">食べたものを思い出すための写真です。縮小してこの端末の中だけに保存し、外部には送りません。バックアップには含まれません。</p>
    <div class="field"><label for="keepDays">写真を残す期間</label>
      <select id="keepDays">
        ${[[7, '7日'], [30, '30日'], [90, '90日'], [0, '無期限（自分で削除）']].map(([v, l]) => `<option value="${v}" ${Number(state.photoKeepDays == null ? 90 : state.photoKeepDays) === v ? 'selected' : ''}>${l}</option>`).join('')}
      </select>
      <div class="hint">期間を過ぎた写真は、次に開いたときに自動で消えます（記録は消えません）</div></div>
    <div class="small muted" id="photoCountLabel"></div>
  </div>

  ${newsCard()}

  <div class="card">
    <h2>データの保存</h2>
    <p class="small muted" style="margin-top:0">記録はこの端末のブラウザの中だけに保存され、外部には送信されません。機種変更やブラウザのデータ削除で消えるため、ときどきバックアップしてください。</p>
    <div class="meal-actions" style="flex-wrap:wrap">
      <button class="btn small" id="exportBtn">バックアップを保存</button>
      <button class="btn ghost small" id="importBtn">バックアップから復元</button>
      <input type="file" id="importFile" accept="application/json,.json" hidden>
    </div>
    <div class="meal-actions"><button class="btn danger small" id="wipeBtn">すべてのデータを削除</button></div>
  </div>

  <div class="card src">
    <h2>ご注意</h2>
    <p>このツールは健康な人が食事のたんぱく質量の目安を知るためのものです。医療や栄養指導の代わりにはなりません。</p>
    <p><b>腎臓病などでたんぱく質の制限や管理を受けている人は、このツールの値ではなく主治医・管理栄養士の指示を優先してください。</b>（食事摂取基準でも、疾患の管理を目的とした制限や多量摂取が必要な場合はそちらを優先すべきとされています）</p>
    <details class="fold"><summary>食品の値について</summary>
    <p>食品の値は可食部（食べる部分）100gあたりの平均的な値です。実際の食品とは品種・調理法などで差があります。「推定」と表示された値は、成分表で推計値とされているものです。</p>
    </details>
    <details class="fold"><summary>出典（タップで開く）</summary>
    <h3>必要量</h3>
    <p>厚生労働省「日本人の食事摂取基準（2025年版）」策定検討会報告書（令和6年10月）各論 1-2 たんぱく質</p>
    <p class="tiny muted">推奨量・推定平均必要量（p.103の表）／成人の維持必要量 0.73g/kg体重/日（p.90）／推奨量算定係数 1.25（p.92）／高齢者の1.2g/kg体重/日（p.95）／疾患管理の優先（p.96）／目標量（p.95〜96, p.103）</p>
    <p class="tiny muted">乳児（1歳未満）の目安量：0〜5か月 10g、6〜8か月 15g、9〜11か月 25g（p.103）</p>
    <h3>食品のたんぱく質量</h3>
    <p>日本食品標準成分表（八訂）増補2023年から引用（文部科学省 科学技術・学術審議会 資源調査分科会、2026年3月27日掲載のデータ）。「たんぱく質」の列の値を使用。カロリー・PFCを表示するときは、同じ成分表の「エネルギー（kcal）」「脂質」「炭水化物」の列を使用（PFCの割合は、たんぱく質・炭水化物を1gあたり4kcal、脂質を9kcalとして計算）。</p>
    <h3>個数で入れるときの重さ</h3>
    <p>卵：農林水産省「鶏卵の規格」（畜産物の価格安定に関する法律施行規則の規定に基づく鶏卵の規格）の重量区分（例：M 58g以上64g未満）の中央値から、成分表の廃棄率（殻）を除いて計算。目玉焼きなどは、さらに成分表の重量変化率をかけています。</p>
    <p>油・調味料・砂糖の大さじ・小さじ：大さじ15mL・小さじ5mL（すりきり）を、成分表の備考「100mL＝◯g」で重さに換算。備考に換算値がないもの（バターなど）は大さじ・小さじを出さず、gで入れる形です。</p>
    <p>粉末スープ1袋・梅干し1個・カレールウ1皿分などは一般的な目安の重さです。袋に「1食分◯g」とあるときは、gで入れるのが正確です。</p>
    <p>飲み物のmL：成分表の備考に「100mL＝◯g」がある食品はその値で換算。記載がない飲み物（豆乳・お茶・コーヒーなど）は1mL＝1gの目安で換算し、記録に「約・目安」と表示（成分表の飲み物の換算値はほとんどが100mL＝97〜108gの範囲）。</p>
    <p>調理前の重さで入れる場合と「1本分」「乾めん100g分」など：日本食品標準成分表（八訂）増補2023年 第1章「調理方法の概要及び重量変化率表」の重量変化率を使って換算。</p>
    <p>ごはん茶碗1杯、食パン1枚、納豆1パック、豆腐1/2丁、トマト1個、レタス1人前、くだもの1個、刺身1切れ、調理前の量（ささみ1本50gなど）、かき1個・あじ1尾・薄切り肉1枚などの重さは、自治体の資料や管理栄養士の目安量一覧などを参考にした一般的な目安です。鍋・すき焼き・焼肉・カレー・みそ汁の具の初期の量、魚介1切れ・1個の重さ、鍋の味（だし・たれ）の量もこのツール独自の一般的な目安です。たんぱく質の値は、すべて食品成分表から計算しています。</p>
    <p>ギリシャヨーグルト（無脂肪・無糖）の値は、米国農務省の食品データベース（USDA FoodData Central）によります（100gあたり たんぱく質10.2g・59kcal）。</p>
    <p>「外食（公式発表値）」は、各社が公式に公表している栄養成分の値です（ケンタッキーフライドチキン「栄養成分表」2026/11/25現在。食塩相当量・食物繊維・カルシウム・鉄・ビタミンA・B1・B2・Cも同じ表から）。「市販品（公式発表値）」も同じく、メーカーが公表している栄養成分表示の値です（ビール類：各社の公式サイト・商品の表示、2026年11月確認。幅のある値は中間をとっています。リニューアルで変わることがあります）。</p>
    <p>「料理（目安）」は、成分表にない料理を一般的な家庭の分量で材料に分け、材料ごとに成分表の値から計算した目安です（材料と分量は各料理の記録画面に表示）。カロリーは油や砂糖の量で大きく変わるので、おおまかな目安です。</p>
    <p>プロテイン（粉末）：成分表には載っていないため、市販品（明治 ザバス ソイプロテイン100など、1食分28gでたんぱく質20.0g）の栄養成分表示から、粉の約7割（71.4%）をたんぱく質として計算しています。商品によって6〜8割程度の差があるので、使っている商品はマイリストへの登録（100gあたり）をおすすめします。カロリー・脂質・炭水化物も同じ商品（1食分28gで107kcal・脂質1.2g・炭水化物4.2g）から計算しています。</p>
    <h3>ほかの栄養素（設定でオンにしたとき）</h3>
    <p>食品の値：日本食品標準成分表（八訂）増補2023年から引用（2026年3月27日掲載のデータ）。食塩相当量、食物繊維総量、カルシウム、鉄、ビタミンA（レチノール活性当量）、D、E（α-トコフェロール）、K、B1、B2、ナイアシン当量、B6、B12、葉酸、パントテン酸、Cの列を使用。Tr（微量）は0、括弧付きの推定値はそのまま使い、値のない食品（－）は「不明」として扱います（調味料・だし・飲料の「－」は0とみなします）。ビオチンは値のない食品が多いため表示していません。</p>
    <p>基準の値：厚生労働省「日本人の食事摂取基準（2025年版）」策定検討会報告書の各表（食物繊維：各論1-4 炭水化物、ビタミン：各論1-6、ナトリウム・カルシウム：各論1-7 多量ミネラル、鉄：各論1-7 微量ミネラル）。妊婦・授乳婦は付加量を足した値。鉄は女性（10〜64歳）の場合、月経なしの値を基本に、月経ありの値も併記しています。</p>
    <p class="tiny muted">料理は材料から計算した目安で、ゆでる・煮るなどの調理で減る分（水に溶けるビタミンなど）は入っていません。公式値の市販品・外食は、公表されている栄養素だけ使います（KFCは食塩相当量・食物繊維・カルシウム・鉄・ビタミンA・B1・B2・C。ナイアシンは当量でないため使いません）。それ以外と一般的な目安は「不明」です。</p>
    <h3>カロリーの目安・BMI・体重</h3>
    <p>同 各論 1-1 エネルギー：推定エネルギー必要量（参考表2、p.78）、目標とするBMIの範囲（表1、p.58）、エネルギーの過不足は体重の変化又はBMIで評価する（p.76、参考表2の注）。たんぱく質の目標量の上限20%エネルギー：各論 1-2 たんぱく質（p.95〜96）。</p>
    </details>
    <p class="tiny muted">たんぱく質ノート v1.4.45</p>
  </div>`;
}

/* =========================================================
   シート（追加・編集）
   ========================================================= */
let sheetCtx = null;
/* スマホのキーボードが出たとき、シートをキーボードの上に収める（iPhoneは画面の高さが変わらず、下がキーボードに隠れるため） */
function fitSheet() {
  const sh = $('#sheet');
  if (!sh || sh.hidden) return;
  const vv = window.visualViewport;
  const visH = vv ? vv.height : window.innerHeight;
  const kb = vv ? Math.max(0, window.innerHeight - vv.height - vv.offsetTop) : 0;
  sh.style.bottom = kb > 1 ? kb + 'px' : '';
  sh.style.paddingBottom = kb > 1 ? '0' : '';
  const h = Math.round(visH * (kb > 1 ? 0.96 : 0.92));
  sh.style.maxHeight = h + 'px';
  sh.style.height = sh.classList.contains('tall') ? h + 'px' : '';
}
if (window.visualViewport) {
  window.visualViewport.addEventListener('resize', fitSheet);
  window.visualViewport.addEventListener('scroll', fitSheet);
}
window.addEventListener('resize', fitSheet);

function openSheet(title, bodyHtml, onMount, opts = {}) {
  const sh = $('#sheet');
  const tt = $('#toast'); if (tt && !tt.classList.contains('top')) tt.hidden = true; // 下に出ているお知らせがボタンにかぶらないように
  sh.classList.toggle('tall', !!opts.tall);
  sh.classList.toggle('editing', !!opts.editing); // 記録の修正中は見出しの色を変える
  sh.innerHTML = `<div class="sheet-head"><h3>${title}</h3><button class="close-x" data-close="1" aria-label="閉じる">✕</button></div>
    <div class="sheet-body">${bodyHtml}</div>`;
  sh.hidden = false;
  $('#sheetBackdrop').hidden = false;
  document.body.style.overflow = 'hidden';
  fitSheet();
  if (onMount) onMount(sh);
}
function closeSheet() {
  const sh = $('#sheet');
  if (state.mlDraft && sh.querySelector('#mlForm')) { delete state.mlDraft; saveState(); } // 登録画面を自分で閉じたら下書きは捨てる
  sh.hidden = true;
  sh.classList.remove('tall', 'editing');
  multiCtx = null;
  playPendingHop();
  ['bottom', 'paddingBottom', 'maxHeight', 'height'].forEach(k => { sh.style[k] = ''; });
  $('#sheetBackdrop').hidden = true;
  document.body.style.overflow = '';
  sheetCtx = null;
}

/* =========================================================
   まとめて入力：いくつかの言葉を一度に入れて、言葉ごとの候補から記録する
   ========================================================= */
let multiCtx = null;
const MULTI_PH = ['ごはん', '納豆', 'みそ汁', 'ゆで卵', '牛乳', 'バナナ', 'ヨーグルト', 'サラダ'];
function openMulti(meal) {
  multiCtx = { meal, terms: ['', '', ''], open: {}, done: {}, added: [], cache: {}, mode: 'search' };
  openMultiInput();
}
function openMultiInput() {
  const c = multiCtx;
  sheetCtx = { meal: c.meal, multi: 'input', mode: c.mode || 'search', q: '' };
  while (c.terms.length < 3) c.terms.push('');
  const segs = [['ml', 'マイリスト'], ['hist', '履歴'], ['search', 'よく使う']];
  openSheet(`${mealLabel(c.meal)}に追加`, `
    <div id="mInputs">${c.terms.map((t, i) => multiInputRow(t, i)).join('')}</div>
    <div class="m-actions">
      <button class="btn ghost small" data-mrow="1">＋ 行を増やす</button>
      <button class="btn" id="mGo">探す</button>
    </div>
    <div class="tiny muted" style="margin:-2px 0 6px">いくつか食べたときは、1行に1つずつ入れて一度に探せます</div>
    ${photoStripForSheet()}
    <div class="seg" id="seg">${segs.map(([k, l]) => `<button data-mode="${k}" class="${k === sheetCtx.mode ? 'on' : ''}">${l}</button>`).join('')}</div>
    <div id="results"></div>
  `, sh => {
    sh.querySelectorAll('.mterm').forEach(inp => inp.addEventListener('keydown', ev => {
      if (ev.key !== 'Enter') return;
      ev.preventDefault(); inp.blur(); runMulti();
    }));
    renderResults();
  }, { tall: true });
}
function multiInputRow(t, i) {
  const ph = i === 0 ? `食べたものを入力（例：${MULTI_PH[0]}）` : `（例）${MULTI_PH[i % MULTI_PH.length]}`;
  return `<input class="search mterm" data-i="${i}" type="search" enterkeyhint="search" autocomplete="off" value="${esc(t)}" placeholder="${esc(ph)}" style="margin-bottom:8px">`;
}
function readMultiInputs() {
  multiCtx.terms = Array.from(document.querySelectorAll('.mterm')).map(x => x.value);
}
function runMulti() {
  readMultiInputs();
  const terms = multiCtx.terms.map(t => t.trim()).filter(Boolean);
  if (!terms.length) { toast('食べたものを1つ以上入れてください'); return; }
  if (!foodsReady) { toast('食品データを読み込み中です'); return; }
  if (multiCtx.list && multiCtx.list.join('\n') !== terms.join('\n')) multiCtx.done = {}; // 言葉が変わったら ✓ の位置がずれるので消す（記録はそのまま）
  multiCtx.list = terms;
  multiCtx.open = {};
  multiCtx.scroll = 0;
  openMultiResults();
}
/* 1つの言葉の候補（ふつうの検索と同じ順：マイリスト→料理→一般的な目安→成分表→その他の料理） */
function multiCands(term) {
  const cache = multiCtx ? multiCtx.cache : (multiCands.c || (multiCands.c = {}));
  if (cache[term]) return cache[term];
  const terms = widenTerms(term);
  const widened = terms.join(' ') !== term.trim();
  const q = terms[0], extra = widened ? terms.slice(1) : [];
  let res = searchFoods(q);
  if (extra.length) {
    const groups = [res].concat(extra.map(t => searchFoods(t)));
    const merged = [];
    const add = f => { if (!merged.includes(f)) merged.push(f); };
    groups.forEach(g => g.slice(0, 3).forEach(add));
    groups.forEach(g => g.slice(3).forEach(add));
    res = merged;
  }
  const nq = norm(q);
  const mine = state.myList.filter(it => norm(it.name).includes(nq));
  const gens = GENERIC_ITEMS.filter(it => (it.need ? it.need.test(term) : norm(it.name + ' ' + it.keys).includes(nq)));
  const dishes = searchDishes(q);
  for (const t of extra) for (const d of searchDishes(t)) if (!dishes.some(x => x.id === d.id)) dishes.push(d);
  // 魚の名前だけで探したとき：魚（生）→ 塩焼き → 煮付け… の順に
  const srcD = d => DISHES.find(x => x.id === d.id) || {}; // searchDishes は表示用に作り直したものを返すので、元の定義を見る
  const fishKey = d => { const o = srcD(d); return o.fish && FISH_KEYS[o.fish] && FISH_KEYS[o.fish].includes(nq); };
  const fishD = res.length ? dishes.filter(fishKey).sort((a, b) => srcD(a).ord - srcD(b).ord) : [];
  { // 入れた言葉と表示名がぴったり同じもの（「赤ワイン」→ 赤ワイン）を先頭に
    const nt = norm(term.trim());
    const k = res.findIndex(f => norm(dispName(f.main).name) === nt);
    if (k > 0) res = [res[k]].concat(res.filter((_, i) => i !== k));
  }
  if (fishD.length) { // 生の魚（切り身・1尾）を先頭に
    const raw = foodByCode.get(FISH_RAW[srcD(fishD[0]).fish]);
    if (raw) res = [raw].concat(res.filter(f => f !== raw));
  }
  const dTop = res.length ? dishes.filter(d => !fishD.includes(d) && nq.length >= 3 && norm(d.name).startsWith(nq)) : dishes;
  const dLow = dishes.filter(d => !dTop.includes(d) && !fishD.includes(d));
  const out = [
    ...mine.map(it => ({ k: 'ml', id: it.id })),
    ...(res.length ? [] : gens.map(g => ({ k: 'gen', id: g.id }))), // 成分表に無いもの（プロテインなど）は、一般的な目安を先に
    ...dTop.map(d => ({ k: 'dish', id: d.id })),
    ...(res.length ? gens.map(g => ({ k: 'gen', id: g.id })) : []),
    ...res.slice(0, fishD.length ? 1 : 0).map(f => ({ k: 'food', id: f.code, q: term })),
    ...fishD.map(d => ({ k: 'dish', id: d.id })),
    ...res.slice(fishD.length ? 1 : 0, 5).map(f => ({ k: 'food', id: f.code, q: term })),
    ...dLow.map(d => ({ k: 'dish', id: d.id })),
    ...res.slice(5, 40).map(f => ({ k: 'food', id: f.code, q: term })),
  ];
  cache[term] = { list: out, widened: widened ? terms : null };
  return cache[term];
}
/* 候補をそのまま記録するときのデータ（量は前回の入れ方・1個の目安など） */
function multiEntry(cand, remember) {
  const meal = multiCtx ? multiCtx.meal : 'b';
  if (cand.k === 'ml') { const it = state.myList.find(x => x.id === cand.id); return it ? mlEntry(it, meal) : null; }
  if (cand.k === 'dish') {
    const d = DISHES.find(x => x.id === cand.id); const it = d && dishItem(d);
    return it ? itemEntryData(it, dishDefVal(d), meal) : null;
  }
  if (cand.k === 'gen') {
    const g = GENERIC_ITEMS.find(x => x.id === cand.id);
    return g ? itemEntryData(g, (state.recent['gen:' + g.id] || {}).v || g.defVal, meal) : null;
  }
  const f = foodByCode.get(cand.id);
  return f ? foodEntryData(amountState(f, { q: cand.q }), meal, remember) : null;
}
function multiCandSub(cand) {
  if (cand.k === 'food') { const f = foodByCode.get(cand.id); return dispName(f.main).note; }
  if (cand.k === 'dish') { const d = DISHES.find(x => x.id === cand.id); return d && d.cat ? d.cat : d && d.fixed != null ? (d.src === 'kfc' ? '外食' : '市販品') : '料理（目安）'; }
  if (cand.k === 'gen') return '一般的な目安';
  return 'マイリスト';
}
function openMultiResults() {
  const c = multiCtx;
  sheetCtx = { meal: c.meal, multi: 'results' };
  const total = r1(c.added.reduce((a, x) => a + (Number(x.protein) || 0), 0));
  const groups = c.list.map((term, i) => {
    const { list, widened } = multiCands(term);
    const one = c.list.length === 1;
    const n = c.open[i] ? 40 : one ? 12 : 4;
    const rows = list.slice(0, n).map((cand, j) => {
      const e = multiEntry(cand, false);
      if (!e) return '';
      const key = `${i}:${j}`;
      const done = c.done[key];
      const nut = showNut() ? (x => x.kcal == null ? '' : `・${x.kcal}kcal`)(entryNut(e)) : '';
      return `<div class="mrow">
        <button class="food" data-mpick="${key}">
          ${guRow(cand, e, nut) || `<span class="nm"><div>${esc(dispName(e.name).name)}</div><div class="sub">${esc(entryAmountLabel(e))}${nut}${multiCandSub(cand) ? '・' + esc(multiCandSub(cand)) : ''}</div></span>`}
          <span class="p">${fmt(e.protein)}g</span>
        </button>
        <button class="madd ${done ? 'done' : ''}" data-madd="${key}" aria-label="${esc(e.name)}を記録">${done ? '✓' : '＋'}</button>
      </div>`;
    }).join('');
    return `<div class="mgroup">
      <div class="mhead"><b>${esc(term)}</b><span class="tiny muted">${list.length ? list.length + '件' : ''}</span></div>
      ${widened ? `<div class="tiny muted" style="padding:2px 4px 4px">「${esc(term)}」では見つからなかったので、${widened.map(t => '「' + esc(t) + '」').join('と')}で探しました</div>` : ''}
      ${rows || `<div class="empty small">見つかりませんでした。別の言い方で試すか、市販品ならWebで調べてマイリストに登録できます</div>`}
      ${list.length > n ? `<button class="btn ghost small block" data-mmore="${i}">もっと見る</button>` : ''}
      <div class="mhelp"><span class="tiny muted">市販品が見つからないとき：</span><button class="linkbtn" data-web="${esc(term)}">Webで調べる</button><button class="linkbtn" data-mlnew="${esc(term)}">マイリストに登録</button></div>
    </div>`;
  }).join('');
  openSheet(`${mealLabel(c.meal)}に追加`, `
    <div class="small muted" style="margin-bottom:4px">＋を押すと、表示の量で記録します。量を変えたいときは名前をタップ</div>
    <div class="meal-actions" style="margin:0 0 6px"><button class="btn ghost small" data-medit="1">← 言葉を直す・足す</button></div>
    ${groups}
    <div class="mfoot"><span class="small">${c.added.length ? `記録した：<b>${c.added.length}品</b>・たんぱく質 <b>${fmt(total)}g</b>` : 'まだ記録していません'}</span>
      <button class="btn" data-mfinish="1">完了</button></div>
  `, sh => { const b = $('.sheet-body', sh); if (b && c.scroll) b.scrollTop = c.scroll; }, { tall: true });
}
/* 具を選べる料理（みそ汁）の候補行：名前をタップすると具を選べることがわかるように */
function guRow(cand, e, nut) {
  if (cand.k !== 'dish') return '';
  const d = DISHES.find(x => x.id === cand.id);
  if (!d || !d.gu) return '';
  const labels = d.gu.filter(g => (e.gu || []).includes(g[0])).map(g => g[1]);
  const dsh = d.dashi && e.dashi ? (d.dashi.find(x => x[0] === e.dashi) || [])[1] : '';
  return `<span class="nm"><div>${esc(d.name)} <span class="gu-tag">具を選ぶ ›</span></div><div class="sub">${dsh ? '味：' + esc(dsh) + '・' : ''}${labels.length ? '具：' + esc(labels.join('・')) : '具なし'}・${esc(entryAmountLabel(e))}${nut}</div></span>`;
}
function multiCandAt(key) {
  const [i, j] = key.split(':').map(Number);
  const term = multiCtx.list[i];
  return term ? multiCands(term).list[j] : null;
}
function multiSaveScroll() {
  const b = $('#sheet .sheet-body');
  if (multiCtx && b) multiCtx.scroll = b.scrollTop;
}
function multiAdd(key) {
  const cand = multiCandAt(key);
  if (!cand) return;
  if (cand.k === 'ml') { const it = state.myList.find(x => x.id === cand.id); if (it && it.kind === 'food' && !foodsReady) return; }
  const e = multiEntry(cand, true);
  if (!e) return;
  addEntry(viewDate, e);
  multiCtx.done[key] = true;
  multiCtx.added.push({ name: e.name, protein: e.protein });
  multiSaveScroll();
  render();
  openMultiResults();
}
function multiPick(key) {
  const cand = multiCandAt(key);
  if (!cand) return;
  multiSaveScroll();
  multiCtx.done[key] = true; // 量を変えて記録したら ✓（記録しなかったときは戻すときに外す）
  multiCtx.pending = key;
  multiCtx.returnTo = true;
  sheetCtx = { meal: multiCtx.meal };
  if (cand.k === 'ml') adjustMl(cand.id);
  else if (cand.k === 'dish') { const d = DISHES.find(x => x.id === cand.id); const it = d && dishItem(d); if (it) openItemAmount(it, null, dishDefVal(d)); }
  else if (cand.k === 'gen') { const g = GENERIC_ITEMS.find(x => x.id === cand.id); if (g) openItemAmount(g, null, (state.recent['gen:' + g.id] || {}).v || g.defVal); }
  else openAmount(cand.id, { meal: multiCtx.meal, q: cand.q });
}
/* ✕・背景・Esc：まとめて入力の途中で量の画面を開いていたら候補へ戻る */
function closeOrBack() {
  if (nutriCtx && nutriCtx.back) { const m = nutriCtx.mode; nutriCtx = null; openNutriSheet(m); return; } // 内訳 → 栄養素の詳細へ戻る
  if (nutriCtx) nutriCtx = null;
  if (regCtx && sheetCtx && sheetCtx.reg && sheetCtx.reg !== 'search') { openMlSearch(); return; } // 登録の量の画面 → 探す画面へ
  if (regCtx && sheetCtx && sheetCtx.reg === 'search') { regCtx = null; closeSheet(); return; }
  if (multiCtx && multiCtx.returnTo && sheetCtx && !sheetCtx.multi && !sheetCtx.editing) {
    if (multiCtx.pending) { delete multiCtx.done[multiCtx.pending]; multiCtx.pending = null; }
    multiCtx.returnTo = false;
    openMultiResults(); return;
  }
  const had = multiCtx && multiCtx.added.length;
  const n = had ? multiCtx.added.length : 0;
  const total = had ? r1(multiCtx.added.reduce((a, x) => a + (Number(x.protein) || 0), 0)) : 0;
  multiCtx = null;
  closeSheet();
  if (had) toast(`${n}品・たんぱく質 ${fmt(total)}g を記録しました`);
}

/* めだかをタップ：ぴょんと跳ねて画面の真ん中で大きく見せ、元の場所へ戻る */
function hopMedaka(img) {
  if (!img || hopMedaka.busy || !img.animate) return;
  if (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const r = img.getBoundingClientRect();
  const big = Math.min(3, (Math.min(window.innerWidth, 560) * 0.62) / r.width);
  const dx = window.innerWidth / 2 - (r.left + r.width / 2);
  const dy = window.innerHeight * 0.42 - (r.top + r.height / 2);
  const fly = img.cloneNode();
  Object.assign(fly.style, { position: 'fixed', left: r.left + 'px', top: r.top + 'px', width: r.width + 'px', height: r.height + 'px', margin: 0, zIndex: 50, pointerEvents: 'none', animation: 'none', filter: 'drop-shadow(0 10px 18px rgba(0,0,0,.18))' });
  document.body.appendChild(fly);
  img.style.visibility = 'hidden';
  hopMedaka.busy = true;
  const at = (x, y, s, rot = 0) => `translate(${x}px, ${y}px) scale(${s}) rotate(${rot}deg)`;
  const a = fly.animate([
    { transform: at(0, 0, 1), offset: 0 },
    { transform: at(0, 6, 1.08, 0), offset: 0.06 },                                  // ちょっとしゃがんで
    { transform: at(dx * 0.45, dy * 0.45 - 90, big * 0.6, -12), offset: 0.24 },      // ぴょん
    { transform: at(dx, dy, big * 1.06, 4), offset: 0.38 },                           // 真ん中に着地
    { transform: at(dx, dy, big * 0.97, -2), offset: 0.46 },
    { transform: at(dx, dy, big, 0), offset: 0.54 },
    { transform: at(dx, dy, big, 0), offset: 0.70 },                                  // 少し止まって見せる
    { transform: at(dx * 0.5, dy * 0.5 - 60, big * 0.55, 10), offset: 0.86 },        // ぴょんと戻る
    { transform: at(0, 0, 1, 0), offset: 1 },
  ], { duration: 2200, easing: 'ease-in-out' });
  const done = () => { fly.remove(); img.style.visibility = ''; hopMedaka.busy = false; };
  a.onfinish = done; a.oncancel = done;
}

/* --- 食品を探す --- */
function openAdd(meal) {
  // 追加画面は「まとめて入力」と同じ形（1つだけなら1行目だけ入れて「探す」）
  openMulti(meal);
}
function mealLabel(m) { return (MEALS.find(x => x[0] === m) || [, ''])[1]; }
function setSeg(mode) {
  document.querySelectorAll('#seg button').forEach(b => b.classList.toggle('on', b.dataset.mode === mode));
}

function foodRow(f, extra = '') {
  return `<button class="food" data-pick="${f.code}" ${extra}>
    <span class="nm"><div>${esc(dispName(f.main).name)}</div><div class="sub">${esc([dispName(f.main).note, f.group, f.sub].filter(Boolean).join('・'))}${f.f === 1 ? '・推定値' : ''}</div></span>
    <span class="p">${fmt(f.p)}g<small>/100g</small></span>
  </button>`;
}

/* ---------- マイリスト ---------- */
const ML_KIND_LABEL = { food: '食材', prod: '市販品', menu: 'メニュー', dish: '料理', gen: '目安' };
function mlSorted() {
  return state.myList.slice().sort((a, b) => ((state.recent['ml:' + b.id] || {}).n || 0) - ((state.recent['ml:' + a.id] || {}).n || 0));
}
function mlAmountLabel(it) {
  if (it.kind === 'food') return it.desc || `${fmt(it.grams)}g`;
  if (it.kind === 'dish' || it.kind === 'gen') { const e = mlEntry(it, 'b'); return e ? entryAmountLabel(e) : ''; }
  if (it.kind === 'menu') return '1食';
  if (it.basis === '100g') return `${fmt(it.defGrams || 100)}g`;
  return it.unit || '1個';
}
/* マイリストの1件を、登録した量のまま記録データにする */
function mlEntry(it, meal) {
  if (it.kind === 'dish' || it.kind === 'gen') { // 料理・一般的な目安（具・量・味もそのまま）
    const item = mlItemFull(it);
    if (!item) return null;
    return Object.assign(itemEntryData(item, it.qty, meal, it.id), { name: it.name });
  }
  if (it.kind === 'food') {
    const f = foodByCode.get(it.code);
    if (!f) return null;
    return Object.assign({ meal, mlId: it.id, code: it.code, name: it.name, grams: it.grams, protein: proteinFor(f, it.grams), amode: it.amode, ulabel: it.ulabel, count: it.count, raw: it.raw, desc: it.desc }, foodNut(f, it.grams));
  }
  const item = mlItem(it);
  const is100 = item.basis === '100g';
  const v = is100 ? (it.defGrams || 100) : 1;
  return {
    meal, mlId: it.id, kind: it.kind, refId: it.id, name: it.name, unit: item.unit, basis: item.basis,
    perUnit: item.protein, qty: is100 ? null : v, grams: is100 ? v : null, protein: itemProtein(item, v),
    perKcal: item.kcal ?? null, perFat: item.fat ?? null, perCarb: item.carb ?? null, ...itemNut(item, v),
  };
}
/* 料理・目安のマイリストから、量を入れる画面用の item を作る */
function mlItemFull(it) {
  if (it.kind === 'gen') return GENERIC_ITEMS.find(x => x.id === it.refId) || null;
  const d = DISHES.find(x => x.id === it.refId);
  if (!d || (!foodsReady && d.fixed == null)) return null;
  return d.gu ? guDishItem(d, it.gu || d.guDef, { ga: it.ga, dashi: it.dashi }) : dishItem(d);
}
function mlItem(it) {
  const nut = { kcal: it.kcal ?? null, fat: it.fat ?? null, carb: it.carb ?? null };
  if (it.kind === 'menu') return Object.assign({ kind: 'menu', id: it.id, name: it.name, unit: '1食', protein: it.protein, basis: 'unit' }, nut);
  return Object.assign({ kind: 'prod', id: it.id, name: it.name, unit: it.basis === '100g' ? '100g' : (it.unit || '1個'), protein: it.protein, basis: it.basis === '100g' ? '100g' : 'unit' }, nut);
}
function mlProteinShown(it) {
  const e = mlEntry(it, 'b');
  return e ? e.protein : 0;
}
function mlRow(it) {
  const p = foodsReady || it.kind === 'prod' || it.kind === 'menu' ? `${fmt(mlProteinShown(it))}g` : '…';
  return `<div class="mlrow">
    <button class="food" data-mlrec="${it.id}">
      <span class="nm"><div>${esc(it.name)}</div><div class="sub">${esc(mlAmountLabel(it))}・${ML_KIND_LABEL[it.kind]}</div></span>
      <span class="p">${p} <span class="plus">＋</span></span>
    </button>
    <button class="adj" data-mladj="${it.id}" aria-label="量を変えて記録">量</button>
  </div>`;
}

/* 過去の記録から、同じ内容（同じ量）のものを1件ずつ新しい順に */
function entryKey(e) {
  if (e.code) return `c:${e.code}:${e.grams}:${e.desc || ''}`;
  return `${e.kind || 'my'}:${e.refId || e.myId || e.name}:${e.basis === '100g' ? e.grams : e.qty}` + (e.gu ? ':' + JSON.stringify([e.gu, e.ga || {}, e.dashi || '']) : '');
}
function historyItems(limit = 40) {
  const seen = new Set();
  const out = [];
  for (const d of Object.keys(state.days).sort().reverse()) {
    const arr = state.days[d];
    for (let k = arr.length - 1; k >= 0; k--) {
      const e = arr[k];
      const key = entryKey(e);
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(e);
      if (out.length >= limit) return out;
    }
  }
  return out;
}
function entryAmountLabel(e) {
  if (e.desc) return e.desc;
  if (e.kind === 'gen' && e.basis === '100g') return (e.refId === 'gen-protein' || /プロテイン/.test(e.name || '') ? '粉' : '') + `${fmt(e.grams)}g`;
  if (e.code || e.basis === '100g') return `${fmt(e.grams)}g`;
  const u = e.unit || '1食';
  const m = u.match(/^1([^\d（()）]+)$/); // 「1杯」「1個」なら「2杯」「1.5個」のように（カッコ付きの単位は × 表記のまま）
  return m ? `${fmt(e.qty)}${m[1]}` : Number(e.qty) === 1 && /^1/.test(u) ? u : `${fmt(e.qty)} × ${u}`;
}

function renderResults() {
  const box = $('#results');
  if (!box) return;
  const mode = sheetCtx.mode;
  if (mode === 'ml') {
    const list = mlSorted();
    box.innerHTML = (list.length
      ? `<div class="list-label">タップで${mealLabel(sheetCtx.meal)}に記録（登録した量）。「量」で量を変えて記録</div>` + list.map(mlRow).join('')
      : `<div class="empty">マイリストはまだ空です。<br>よく食べるものを入れておくと、ここからタップ1回で記録できます。<br><span class="small">食材は、記録するときの「☆ この量でマイリストへ」で入ります。</span></div>`) +
      `<div class="meal-actions"><button class="btn ghost small block" data-mlnew="1">＋ 市販品・メニューを登録</button></div>`;
    return;
  }
  if (mode === 'hist') {
    const list = historyItems();
    sheetCtx.hist = list;
    box.innerHTML = list.length
      ? `<div class="list-label">タップするとすぐ${mealLabel(sheetCtx.meal)}に記録します（同じ量）</div>` +
        list.map((e, i) => `<button class="food" data-hist="${i}">
          <span class="nm"><div>${esc(dispName(e.name).name)}</div><div class="sub">${esc(entryAmountLabel(e))}</div></span>
          <span class="p">${fmt(e.protein)}g <span class="plus">＋</span></span></button>`).join('')
      : '<div class="empty">まだ記録がありません。「食材」から探してください。</div>';
    return;
  }
  if (!foodsReady) { box.innerHTML = '<div class="empty">食品データを読み込み中…</div>'; return; }
  let q = sheetCtx.q.trim();
  if (!q) {
    const recent = Object.entries(state.recent)
      .filter(([k]) => foodByCode.has(k))
      .sort((a, b) => b[1].t - a[1].t).slice(0, 8).map(([k]) => foodByCode.get(k));
    let html = '';
    if (state.myList.length) {
      const mls = mlSorted();
      html += `<div class="list-label">マイリスト</div>` + mls.slice(0, 5).map(mlRow).join('') +
        (mls.length > 5 ? `<div class="meal-actions"><button class="btn ghost small block" data-mode="ml">マイリストをすべて見る（${mls.length}件）</button></div>` : '');
    }
    if (recent.length) html += `<div class="list-label">最近使った食材</div>` + recent.map(f => foodRow(f)).join('');
    html += `<div class="list-label">よく使う食材</div>` + GENERIC_ITEMS.filter(it => !it.need).map(genRow).join('') + STAPLES.map(s => {
      const f = foodByCode.get(s.code);
      return f ? `<button class="food" data-pick="${f.code}">
        <span class="nm"><div>${esc(s.label)}</div><div class="sub">${esc(f.main)}</div></span>
        <span class="p">${fmt(f.p)}g<small>/100g</small></span></button>` : '';
    }).join('');
    box.innerHTML = html;
    return;
  }
  // 見つからない言葉（例：「鴨鍋」）は、中に含まれる言葉（「鴨」）で探し直す
  const orig = q;
  const terms = widenTerms(q);
  const widened = terms.join(' ') !== orig;
  q = terms[0];
  const extra = widened ? terms.slice(1) : [];
  let res = searchFoods(q);
  if (extra.length) {
    // 2つの言葉で探したときは、それぞれの上位3件を先に並べる（「納豆」「ごはん」が両方すぐ見えるように）
    const groups = [res].concat(extra.map(t => searchFoods(t)));
    const merged = [];
    const add = f => { if (!merged.includes(f)) merged.push(f); };
    groups.forEach(g => g.slice(0, 3).forEach(add));
    groups.forEach(g => g.slice(3).forEach(add));
    res = merged;
  }
  const nq = norm(q);
  const mine = state.myList.filter(it => norm(it.name).includes(nq));
  const gens = GENERIC_ITEMS.filter(it => (it.need ? it.need.test(orig) : norm(it.name + ' ' + it.keys).includes(nq)));
  const dishes = searchDishes(q);
  for (const t of extra) for (const d of searchDishes(t)) if (!dishes.some(x => x.id === d.id)) dishes.push(d);
  // 料理名が探した言葉で始まる（3文字以上：「焼きそば」「カレー」など）料理は上に。それ以外（「卵」で卵かけごはん等）は素材の候補のあとに
  const dTop = res.length ? dishes.filter(d => nq.length >= 3 && norm(d.name).startsWith(nq)) : dishes;
  const dLow = dishes.filter(d => !dTop.includes(d));
  const regBtn = `<div class="meal-actions"><button class="btn ghost small block" data-mlnew="${esc(orig)}">「${esc(orig)}」を市販品・メニューとしてマイリストに登録</button></div>`;
  box.innerHTML =
    (widened ? `<div class="empty small" style="padding:8px 4px">「${esc(orig)}」では見つからなかったので、${terms.map(t => '「' + esc(t) + '」').join('と')}で探しました</div>` : '') +
    (mine.length ? `<div class="list-label">マイリスト</div>${mine.map(mlRow).join('')}` : '') +
    (dTop.length ? `<div class="list-label">料理・外食</div>${dTop.map(dishRow).join('')}` : '') +
    (gens.length ? `<div class="list-label">一般的な目安</div>${gens.map(genRow).join('')}` : '') +
    (mine.length || gens.length || dTop.length || dLow.length ? `<div class="list-label">食品成分表</div>` : '') +
    (res.length
      ? res.slice(0, 5).map(f => foodRow(f)).join('') +
        (dLow.length ? `<div class="list-label">料理・外食</div>${dLow.map(dishRow).join('')}` + (res.length > 5 ? `<div class="list-label">食品成分表（つづき）</div>` : '') : '') +
        res.slice(5).map(f => foodRow(f)).join('') + (res.length >= 60 ? '<div class="empty small">候補が多いので、言葉を足して絞り込んでください（例：「鶏 むね 皮なし」）</div>' : '') +
        `<div class="list-label">市販品・外食などで見つからないとき</div>${regBtn}`
      : `<div class="empty">成分表では見つかりませんでした。<br>ひらがなや別の言い方でも試してください（例：「とり」→「にわとり」、「ごはん」→「めし」）。</div>${regBtn}`);
}

function hitsFor(t) {
  return searchFoods(t).length + searchDishes(t).length + state.myList.filter(it => norm(it.name).includes(norm(t))).length
    + GENERIC_ITEMS.filter(it => !it.need && norm(it.name + ' ' + it.keys).includes(norm(t))).length;
}
let WIDEN_KEYS = null, FOOD_WORDS = null;
const COOK_WORDS = /^(焼き|焼|蒸し|蒸|ゆで|茹で|煮|煮物|揚げ|炒め|いため|油いため|生|水煮|干し|塩焼き|照り焼き|和え|あえ|漬け|定食|弁当|セット|大盛り|特盛|並|丼|鍋)$/;
// 見つからない言葉の中から、探し直す言葉を最大2つ選ぶ（例：「納豆ごはん」→「納豆」「ごはん」、「鴨鍋」→「鴨」）
function widenTerms(q) {
  const toks = String(q).trim().split(/\s+/).filter(Boolean);
  if (!toks.length || hitsFor(q) > 0) return [q];
  const script = c => /[一-龠々]/.test(c || '') ? 'k' : /[ぁ-ゖ]/.test(c || '') ? 'h' : /[ァ-ヶー]/.test(c || '') ? 'K' : 'o';
  if (!FOOD_WORDS) FOOD_WORDS = new Set(foods.flatMap(f => f.kw).filter(w => w.length >= 2 && !/[0-9０-９()（）]/.test(w)));
  if (!WIDEN_KEYS) WIDEN_KEYS = new Set(Object.keys(NORM_ALIASES).filter(k => k.length >= 2 || script(k) === 'k'));
  const terms = [];
  for (const t of toks) {
    if (hitsFor(t) > 0) { terms.push(t); continue; }
    const chars = Array.from(t);
    const cands = [];
    for (let len = chars.length - 1; len >= 1; len--) {
      for (let i = 0; i + len <= chars.length; i++) {
        const sub = chars.slice(i, i + len).join('');
        if (len === 1 && script(sub) !== 'k') continue;
        if (/^の|の$/.test(sub)) continue;
        const ns = norm(sub);
        if (COOK_WORDS.test(sub)) continue; // 「焼き」「蒸し」など調理法だけの言葉では探さない
        const word = WIDEN_KEYS.has(ns) || FOOD_WORDS.has(ns); // 食材名として知っている言葉
        // ひらがな・カタカナの語の途中では切らない（「いちごミルク」→「ごミルク」、「焼きなす」→「焼き」を防ぐ）。知っている言葉ならよい
        const cutHead = i > 0 && script(chars[i - 1]) === script(chars[i]) && script(chars[i]) !== 'k';
        const cutTail = i + len < chars.length && script(chars[i + len - 1]) === script(chars[i + len]) && script(chars[i + len]) !== 'k';
        // 知っている言葉でも、切った残りが1文字なら切らない（「ロースト」→「ロース」＋「ト」、「いかリング」→「かリン」を防ぐ）。ただし「ご飯」「お餅」の「ご」「お」は可
        const runLen = (from, step) => { let n = 0, j = from; const sc0 = script(chars[from]); while (chars[j] && script(chars[j]) === sc0) { n++; j += step; } return n; };
        const restHead = cutHead ? runLen(i - 1, -1) : 0, restTail = cutTail ? runLen(i + len, 1) : 0;
        // 1文字の残りでも、漢字の送りがな（「焼き」の「き」）や「の」、「ご飯」「お餅」の「ご」「お」はよい
        const okHead = restHead === 1 && script(chars[i - 2]) === 'k';
        const okTail = restTail === 1 && (chars[i + len] === 'の' || script(chars[i + len + 1]) === 'k');
        const tinyRest = (cutHead && restHead < 2 && !okHead) || (cutTail && restTail < 2 && !okTail);
        const ss = new Set(Array.from(sub).map(script));
        const mixed = ss.has('h') && ss.has('K') && (cutHead || cutTail); // ひらがなとカタカナがまざる切り方（「かリン」）
        if ((cutHead || cutTail) && (!word || tinyRest || mixed)) continue;
        // カタカナ語を切るとき、残りの先頭が知っている言葉でなければ弱い候補（「ロースト」チキン→「ロース」より「チキン」）
        const restWord = rest => [...WIDEN_KEYS, ...FOOD_WORDS].some(w => w.length >= 3 && norm(rest).startsWith(w));
        const weak = script(chars[i]) === 'K' && cutTail && !restWord(chars.slice(i + len).join(''));
        const known = word || [...WIDEN_KEYS].some(k => script(k[0]) === 'k' && ns.includes(k)) || t.split('の')[0] === sub;
        const sc = len * 10 + (known ? 50 : 0) + (i === 0 ? 20 : 0) + (i + len === chars.length ? 5 : 0);
        cands.push({ sub, i, len, sc: sc - (weak ? 30 : 0), known: known && !weak });
      }
    }
    cands.sort((a, b) => b.sc - a.sc);
    let first = null;
    for (const c of cands) if (hitsFor(c.sub) > 0) { first = c; break; }
    if (!first) { terms.push(t); continue; }
    terms.push(first.sub);
    // 2つ目：重ならない位置にある、食材として知っている言葉（「納豆ごはん」の「ごはん」、「たらこスパゲッティ」の「スパゲッティ」）
    for (const c of cands) {
      if (!c.known || c.i < first.i + first.len && first.i < c.i + c.len) continue;
      if (hitsFor(c.sub) > 0) { terms.push(c.sub); break; }
    }
  }
  return terms;
}
function widenQuery(q) { return widenTerms(q).join(' '); }

/* --- 量を入れる（個数／g／調理前のg） --- */
/* 量の入れ方の初期値（前回の入れ方・個数の目安・飲み物ならmL） */
function amountState(f, opts = {}) {
  const code = f.code;
  const units = unitsFor(f);
  const last = state.recent[code] || {};
  const editing = opts.entry || null;
  const src = editing || opts.preset || null; // 以前の入れ方を再現する
  const mr = mlRate(f);
  const drink = isDrink(f) && !!mr;
  // 飲み物は「量（mL）で」を基本にする
  // ただしコーヒーのように専用の「1杯」があるものは個数で
  let mode = drink && !FOOD_UNITS[f.code] ? 'g' : units.length ? 'unit' : 'g';
  const aset = amountSet(f);
  let unitIdx = 0, count = 1, value = drink ? 200 : aset.def, raw = 100, unit = drink ? 'mL' : 'g';
  if (src && src.amode) {
    mode = src.amode;
    if (mode === 'unit') { const k = units.findIndex(u => u.l === src.ulabel); unitIdx = k >= 0 ? k : 0; count = src.count || 1; if (k < 0) { mode = 'g'; value = src.grams; } }
    if (mode === 'raw') raw = src.raw || 100;
    if (mode === 'g') { if (src.unit === 'mL' && mr) { unit = 'mL'; value = src.ml; } else { unit = 'g'; value = src.grams; } }
  } else if (src && src.grams) {
    mode = 'g'; unit = 'g'; value = src.grams;
  } else if (last.amode) {
    mode = last.amode === 'raw' && !f.rate ? 'g' : last.amode;
    if (mode === 'unit') { const k = units.findIndex(u => u.l === last.ulabel); unitIdx = k >= 0 ? k : 0; if (!units.length) mode = 'g'; }
    if (mode === 'raw') raw = last.raw || 100;
    if (mode === 'g') {
      if (last.unit === 'mL' && mr) { unit = 'mL'; value = last.ml || (drink ? 200 : aset.defMl); }
      else if (last.unit === 'g' || !drink) { unit = 'g'; value = last.g || aset.def; }
    }
  }
  // 「6Pチーズ」「さけるチーズ」のように、探した言葉がそのまま単位の名前に入っていれば、その単位で
  if (!src && opts.q && units.length) {
    const nq = norm(opts.q);
    const k = nq.length >= 2 && !norm(f.name).includes(nq) ? units.findIndex(u => norm(u.l).includes(nq)) : -1;
    if (k >= 0) { mode = 'unit'; unitIdx = k; count = 1; }
  }
  return { code, amode: mode, unitIdx, count, value, raw, unit, editing, units,
    mlId: editing ? editing.mlId : (opts.mlId || null),
    label: editing ? editing.name : (opts.label || null) };
}
function openAmount(code, opts = {}) {
  const f = foodByCode.get(code);
  if (!f) return;
  const staple = STAPLES.find(s => s.code === code);
  const editing = opts.entry || null;
  const mr = mlRate(f);
  const st = amountState(f, opts);
  sheetCtx = Object.assign(sheetCtx || {}, st, {
    meal: editing ? editing.meal : (opts.meal || (sheetCtx && sheetCtx.meal) || guessMeal()),
    reg: !!opts.reg,
  });
  const reg = sheetCtx.reg;
  const units = st.units;
  const title = editing ? esc(dispName(editing.name).name) : esc(opts.label || (staple ? staple.label : dispName(f.main).name));
  openSheet(title, `
    ${photoStripForSheet()}
    <div class="small">${esc(f.name)}</div>
    <div class="tiny muted">100gあたり たんぱく質 ${fmt(f.p)}g${f.f === 1 ? '（推定値）' : f.f === 2 ? '（微量）' : ''}</div>
    ${reg ? '<div class="small muted" style="margin:4px 0">いつも食べる量にして登録します。記録はしません</div>' : `<div class="meal-pick">${MEALS.map(([m, l]) => `<button class="chip ${m === sheetCtx.meal ? 'on' : ''}" data-meal="${m}">${l}</button>`).join('')}</div>`}
    <div class="seg" id="amodeSeg">
      ${units.length ? `<button data-amode="unit">${units.every(u => u.kind === 'spoon') ? '大さじ・小さじで' : '個数で'}</button>` : ''}
      <button data-amode="g">${mr ? '量（mL・g）で' : '重さ（g）で'}</button>
      ${f.rate ? `<button data-amode="raw">調理前の重さで</button>` : ''}
    </div>
    <div id="amodeBody"></div>
    <div class="result"><span>たんぱく質 <span class="tiny muted" id="gramsLabel"></span></span><b id="calc">0g</b></div>
    <button class="btn block" id="saveAmt">${reg ? 'マイリストに登録' : editing ? '修正する' : '記録する'}</button>
    <div class="meal-actions" ${reg ? 'hidden' : ''}><button class="btn ghost small block" id="starBtn">☆ この量でマイリストへ</button></div>
    ${editing ? '<div class="meal-actions"><button class="btn danger small block" id="delEntry">この記録を削除</button></div>' : ''}
  `, () => renderAmountBody(), { editing: !!editing });
}
function renderAmountBody() {
  const c = sheetCtx;
  const f = foodByCode.get(c.code);
  document.querySelectorAll('#amodeSeg button').forEach(b => b.classList.toggle('on', b.dataset.amode === c.amode));
  const box = $('#amodeBody');
  if (c.amode === 'unit') {
    const u = c.units[c.unitIdx];
    box.innerHTML = `
      <div class="chips unit-chips">${c.units.map((x, i) => `<button class="chip ${i === c.unitIdx ? 'on' : ''}" data-uidx="${i}">${esc(x.l)}</button>`).join('')}</div>
      <div class="stepper">
        <button class="step" data-cnt="-0.5" aria-label="減らす">−</button>
        <div class="cnt"><b id="cntVal">${fmt(c.count)}</b><span>${esc(u.c ? u.c : '× ' + u.l)}</span></div>
        <button class="step" data-cnt="0.5" aria-label="増やす">＋</button>
      </div>
      <div class="note">${esc(unitNote(u, f))}</div>`;
  } else if (c.amode === 'raw') {
    box.innerHTML = `
      <div class="amount-box"><input id="rawAmt" type="number" inputmode="decimal" min="0" step="any" value="${fmt(c.raw)}"><span class="u">g</span></div>
      <div class="chips">${[50, 80, 100, 150, 200].map(g => `<button class="chip" data-rawg="${g}">${g}g</button>`).join('')}</div>
      <div class="note">肉のパックの表示など、調理する前（生・乾めんなど）の重さを入れてください。成分表の重量変化率（${f.rate}%）で、この料理の重さに換算します。</div>`;
    $('#rawAmt').addEventListener('input', ev => { c.raw = Number(ev.target.value) || 0; updAmount(); });
  } else {
    box.innerHTML = `
      <div class="amount-box">
        <input id="amt" type="number" inputmode="decimal" min="0" step="any" value="${fmt(c.value)}">
        ${mlRate(f) ? `<div class="seg" style="margin:0;flex:none"><button data-unit="mL" class="${c.unit === 'mL' ? 'on' : ''}">mL</button><button data-unit="g" class="${c.unit === 'g' ? 'on' : ''}">g</button></div>` : '<span class="u">g</span>'}
      </div>
      <div class="chips">${(c.unit === 'mL' ? amountSet(f).ml : amountSet(f).g).map(g => `<button class="chip" data-g="${g}">${g}${c.unit === 'mL' ? 'mL' : 'g'}</button>`).join('')}</div>
      <div class="tiny muted" style="margin-top:6px">${c.unit === 'mL' ? esc(mlNote(f)) : '食べる部分の重さを入れてください'}</div>`;
    $('#amt').addEventListener('input', ev => { c.value = Number(ev.target.value) || 0; updAmount(); });
  }
  updAmount();
}
function updAmount() {
  const f = foodByCode.get(sheetCtx.code);
  const g = currentGrams();
  $('#calc').textContent = `${fmt(proteinFor(f, g))}g`;
  if (showNut() && f.kcal != null) $('#calc').insertAdjacentHTML('beforeend', `<span class="tiny muted" style="font-weight:400">　${foodNut(f, g).kcal}kcal</span>`);
  $('#gramsLabel').textContent = g > 0 && sheetCtx.amode !== 'g' ? `（${fmt(g)}g）` : '';
  $('#saveAmt').disabled = !(g > 0);
  $('#starBtn').disabled = !(g > 0);
}
function currentGrams(c = sheetCtx) {
  const f = foodByCode.get(c.code);
  if (c.amode === 'unit') { const u = c.units[c.unitIdx]; return u ? r1(u.g * c.count) : 0; }
  if (c.amode === 'raw') return f.rate ? r1(c.raw * f.rate / 100) : 0;
  const v = Number(c.value) || 0;
  const mr = mlRate(f);
  return c.unit === 'mL' && mr ? r1(v * mr.r / 100) : v;
}
/* 記録に残す「どう入れたか」 */
function amountMeta(c = sheetCtx) {
  const g = currentGrams(c);
  if (c.amode === 'unit') {
    const u = c.units[c.unitIdx];
    return { amode: 'unit', ulabel: u.l, count: c.count, desc: `${u.l}${c.count !== 1 ? ' ×' + fmt(c.count) : ''}（${fmt(g)}g）` };
  }
  if (c.amode === 'raw') return { amode: 'raw', raw: c.raw, desc: `調理前${fmt(c.raw)}g（${fmt(g)}g）` };
  if (c.unit === 'mL') {
    const est = (mlRate(foodByCode.get(c.code)) || {}).est;
    return { amode: 'g', unit: 'mL', ml: c.value, desc: `${fmt(c.value)}mL（${est ? '約' : ''}${fmt(g)}g${est ? '・目安' : ''}）` };
  }
  return { amode: 'g', unit: 'g', desc: `${fmt(g)}g` };
}
/* 食材の記録データ（量の入れ方 c から） */
function foodEntryData(c, meal, remember = true) {
  const f = foodByCode.get(c.code);
  const grams = currentGrams(c);
  if (!f || !(grams > 0)) return null;
  const staple = STAPLES.find(s => s.code === f.code);
  const meta = amountMeta(c);
  const data = Object.assign({ meal, code: f.code, name: c.label || (staple ? staple.label : dispName(f.main).name), grams, protein: proteinFor(f, grams) }, foodNut(f, grams), meta);
  if (c.mlId) data.mlId = c.mlId;
  if (remember) state.recent[f.code] = Object.assign(state.recent[f.code] || { n: 0 }, { amode: meta.amode, ulabel: meta.ulabel, raw: meta.raw, g: grams, unit: meta.unit, ml: meta.ml });
  return data;
}
/* 料理・目安・市販品の記録データ */
function itemEntryData(it, v, meal, mlId) {
  const is100 = it.basis === '100g';
  return {
    meal, mlId: mlId || undefined, kind: it.kind, refId: it.id, name: it.name, unit: it.unit, basis: is100 ? '100g' : 'unit',
    perUnit: it.protein, qty: is100 ? null : v, grams: is100 ? v : null, protein: itemProtein(it, v),
    perKcal: it.kcal ?? null, perFat: it.fat ?? null, perCarb: it.carb ?? null, ...itemNut(it, v),
    ...(it.sel ? { gu: it.sel.slice(), ga: Object.assign({}, it.ga), ...(it.dashi ? { dashi: it.dashi } : {}) } : {}),
  };
}
/* 記録したあと：まとめて入力の途中なら候補の画面へ戻る */
function afterSave(data) {
  if (multiCtx && multiCtx.returnTo && !(sheetCtx && sheetCtx.editing)) {
    if (data) { multiCtx.added.push({ name: data.name, protein: data.protein }); }
    multiCtx.pending = null;
    multiCtx.returnTo = false;
    render(); openMultiResults(); return;
  }
  closeSheet(); render();
}
function guessMeal() {
  const h = new Date().getHours();
  if (h < 10) return 'b';
  if (h < 15) return 'l';
  if (h < 17) return 's';
  return 'd';
}

/* --- マイリストの登録・編集 --- */
function starCurrentFood() {
  const f = foodByCode.get(sheetCtx.code);
  const grams = currentGrams();
  if (!f || !(grams > 0)) return false;
  const meta = amountMeta();
  if (state.myList.some(x => x.kind === 'food' && x.code === f.code && Math.abs(x.grams - grams) < 0.05)) {
    toast('同じ量ですでにマイリストに入っています'); return true;
  }
  const st = STAPLES.find(x => x.code === f.code);
  const it = Object.assign({ id: uid(), kind: 'food', code: f.code, grams, name: sheetCtx.label || (st ? st.label : dispName(f.main).name) }, meta);
  state.myList.push(it);
  saveState();
  toast(`マイリストに入れました（${it.name} ${mlAmountLabel(it)}）`);
  return true;
}
/* 料理・一般的な目安を、今の量・具・味のままマイリストへ */
function mlSameItem(a, b) {
  return a.kind === b.kind && a.refId === b.refId && Math.abs((a.qty || 0) - (b.qty || 0)) < 0.001 &&
    JSON.stringify(a.gu || null) === JSON.stringify(b.gu || null) && JSON.stringify(a.ga || {}) === JSON.stringify(b.ga || {}) && (a.dashi || null) === (b.dashi || null);
}
function mlFromItem(item, v) {
  return Object.assign({ kind: item.kind === 'gen' ? 'gen' : 'dish', refId: item.id, name: item.name, qty: v },
    item.sel ? { gu: item.sel.slice(), ga: Object.assign({}, item.ga), ...(item.dashi ? { dashi: item.dashi } : {}) } : {});
}
function starCurrentItem() {
  const item = sheetCtx && sheetCtx.item, v = Number(sheetCtx && sheetCtx.val);
  if (!item || !(v > 0) || (item.kind !== 'dish' && item.kind !== 'gen')) return false;
  const it = mlFromItem(item, v);
  if (state.myList.some(x => mlSameItem(x, it))) { toast('同じ内容ですでにマイリストに入っています'); return true; }
  it.id = uid();
  state.myList.push(it);
  saveState();
  toast(`マイリストに入れました（${it.name} ${mlAmountLabel(it)}）`);
  return true;
}
/* マイリストの料理の内容（具・量・味）を直して保存 */
function saveMlItem() {
  const it = state.myList.find(x => x.id === sheetCtx.mlSave);
  const v = Number(sheetCtx.val);
  if (!it || !(v > 0)) return;
  const auto = mlItemFull(it);
  const nx = mlFromItem(sheetCtx.item, v);
  const renamed = auto && it.name !== auto.name; // 自分で名前を変えていたら、その名前を残す
  Object.assign(it, { qty: nx.qty, gu: nx.gu, ga: nx.ga, dashi: nx.dashi }, renamed ? {} : { name: nx.name });
  if (!nx.gu) { delete it.gu; delete it.ga; delete it.dashi; }
  saveState(); toast('保存しました'); closeSheet(); render();
}
function openMlDishForm(it) {
  const item = mlItemFull(it);
  openSheet('マイリストを編集', `
    <form id="mlDishForm" novalidate>
      <div class="small muted">${esc(ML_KIND_LABEL[it.kind])}・${esc(mlAmountLabel(it))}${item ? '・たんぱく質 ' + fmt(mlProteinShown(it)) + 'g' : ''}</div>
      <div class="field" style="margin-top:8px"><label for="mdName">名前</label><input id="mdName" maxlength="60" required value="${esc(it.name)}"></div>
      <button class="btn block" type="submit">名前を保存</button>
      <div class="meal-actions"><button type="button" class="btn ghost small block" id="mdContent">${item && item.sel ? '量・具・味を変える' : '量を変える'}</button></div>
      <div class="meal-actions"><button type="button" class="btn danger small block" id="mlDel">マイリストから削除</button></div>
    </form>`, sh => {
    $('#mlDishForm', sh).addEventListener('submit', ev => {
      ev.preventDefault();
      const name = $('#mdName', sh).value.trim();
      if (!name) return;
      it.name = name; saveState(); toast('保存しました'); closeSheet(); render();
    });
    $('#mdContent', sh).addEventListener('click', () => {
      const cur = mlItemFull(it);
      if (!cur) { toast('食品データを読み込み中です'); return; }
      sheetCtx = null;
      openItemAmount(cur, null, it.qty, null, { mlSave: it.id });
    });
    $('#mlDel', sh).addEventListener('click', () => deleteMl(it));
  });
}

/* ---------- 設定の「メニューを登録」：探して、量や具を決めて、マイリストに登録（記録はしない） ---------- */
let regCtx = null;
function openMlSearch() {
  if (!regCtx) regCtx = { q: '', cands: [] };
  sheetCtx = { reg: 'search' };
  openSheet('メニューを登録', `
    <div class="small muted" style="margin-bottom:6px">よく食べる料理や食材を探して、いつもの量（鍋なら具や味も）にして登録します</div>
    <div style="display:flex;gap:8px;align-items:center"><input class="search" id="regQ" type="search" enterkeyhint="search" autocomplete="off" value="${esc(regCtx.q)}" placeholder="例：鍋、カレー、卵、納豆" style="margin:0"><button class="btn" id="regGo" style="flex:none">探す</button></div>
    <div id="regResults">${regResultsHtml()}</div>
    <div class="list-label">外食の栄養表示などを見て、数字で入れるとき</div>
    <div class="meal-actions"><button class="btn ghost small block" id="regNum">数字で入れる</button></div>
  `, sh => {
    $('#regQ', sh).addEventListener('keydown', ev => { if (ev.key === 'Enter') { ev.preventDefault(); ev.target.blur(); runRegSearch(); } });
  }, { tall: true });
}
function runRegSearch() {
  const q = ($('#regQ') || {}).value || '';
  regCtx.q = q.trim();
  if (!regCtx.q) { toast('探す言葉を入れてください'); return; }
  if (!foodsReady) { toast('食品データを読み込み中です'); return; }
  regCtx.cands = multiCands(regCtx.q).list.filter(c => c.k !== 'ml').slice(0, 30);
  const box = $('#regResults'); if (box) box.innerHTML = regResultsHtml();
}
function regResultsHtml() {
  if (!regCtx || !regCtx.q) return '';
  if (!regCtx.cands.length) return '<div class="empty small">見つかりませんでした。別の言い方で試してください</div>';
  return `<div class="list-label">タップして量や具を決めます</div>` + regCtx.cands.map((cand, i) => {
    const e = multiEntry(cand, false);
    if (!e) return '';
    return `<button class="food" data-regpick="${i}">${guRow(cand, e, '') || `<span class="nm"><div>${esc(dispName(e.name).name)}</div><div class="sub">${esc(entryAmountLabel(e))}${multiCandSub(cand) ? '・' + esc(multiCandSub(cand)) : ''}</div></span>`}<span class="p">${fmt(e.protein)}g ›</span></button>`;
  }).join('');
}
function regPick(i) {
  const cand = regCtx && regCtx.cands[i];
  if (!cand) return;
  sheetCtx = null;
  if (cand.k === 'dish') { const d = DISHES.find(x => x.id === cand.id); const it = d && dishItem(d); if (it) openItemAmount(it, null, dishDefVal(d), null, { reg: true }); }
  else if (cand.k === 'gen') { const g = GENERIC_ITEMS.find(x => x.id === cand.id); if (g) openItemAmount(g, null, (state.recent['gen:' + g.id] || {}).v || g.defVal, null, { reg: true }); }
  else openAmount(cand.id, { q: cand.q, reg: true });
}
function finishReg() {
  regCtx = null;
  closeSheet(); render();
}

/* ---------- 市販品の登録の手助け：Webで調べる／栄養成分表示を貼り付けて読み取る ---------- */
function webSearchUrl(name) { return 'https://www.google.com/search?q=' + encodeURIComponent(`${name} 栄養成分表示`); }
function openWebSearch(name) {
  const w = window.open(webSearchUrl(name), '_blank', 'noopener');
  if (!w) location.href = webSearchUrl(name);
}
/* コピーした栄養成分表示の文字から数字を読み取る。読めなかった項目は入れない
   返り値：{ basis: 'unit'|'100g', unit, grams(1単位のg), defGrams, protein, kcal, fat, carb, salt, fib, scaled } */
function parseNutritionText(raw) {
  let t = String(raw || '').normalize('NFKC')
    .replace(/,(?=\d{3})/g, '').replace(/(\d)\s*[〜～~－−―ー-]\s*(?=\d)/g, '$1〜').replace(/[ \t　]+/g, ' ');
  const NUM = '(\\d+(?:\\.\\d+)?)(?:\\s*〜\\s*(\\d+(?:\\.\\d+)?))?';
  const val = m => m ? (m[2] ? (Number(m[1]) + Number(m[2])) / 2 : Number(m[1])) : null; // 幅がある値は中間
  const pick = (labels, unit, skip) => {
    const re = new RegExp(`(?:${labels})(?![^\\n]{0,4}(?:${skip || '$^'}))[^\\d]{0,14}${NUM}\\s*${unit}`, 'i');
    return val(t.match(re));
  };
  const r = {};
  r.protein = pick('たんぱく質|タンパク質|蛋白質|たん白質|タンパク', 'g');
  r.kcal = pick('エネルギー|熱量|カロリー', 'kcal');
  r.fat = pick('脂質', 'g', '飽和|脂肪酸');
  r.carb = pick('炭水化物', 'g');
  r.fib = pick('食物繊維', 'g');
  r.salt = pick('食塩相当量|食塩', 'g');
  if (r.salt == null) { const na = pick('ナトリウム', 'mg'); if (na != null) r.salt = Math.round(na * 2.54 / 100) / 10; }
  if (r.carb == null) { const su = pick('糖質', 'g'); if (su != null && r.fib != null) r.carb = Math.round((su + r.fib) * 10) / 10; }
  // 何あたりか（最初に出てくる「〜当たり／あたり」）
  const m = t.match(/([^\n]{0,20}?)(?:当たり|あたり|当り)/);
  if (m) {
    const head = m[1].replace(/^.*(?:栄養成分表示|栄養成分|表示|成分)/, '').trim();
    const gm = head.match(/(\d+(?:\.\d+)?)\s*(?:g|ml|mL)/i);
    const um = head.match(/(1|１)\s*([^\d\s(（)）]{1,6})/);
    if (gm && Number(gm[1]) === 100 && !um) { r.basis = '100g'; }
    else if (um) { r.basis = 'unit'; r.unit = '1' + um[2].replace(/分$/, '').replace(/当$/, ''); if (gm) r.grams = Number(gm[1]); }
    else if (gm) { // 「60gあたり」のように単位がないときは 100gあたりに直す
      const g = Number(gm[1]);
      if (g > 0) {
        r.basis = '100g'; r.defGrams = g; r.scaled = g;
        for (const k of ['protein', 'kcal', 'fat', 'carb', 'fib', 'salt']) if (r[k] != null) r[k] = k === 'kcal' ? Math.round(r[k] * 100 / g) : Math.round(r[k] * 1000 / g) / 10;
      }
    }
  }
  return r;
}

/* opts: { name: 初期の名前, meal: 追加画面から開いたときの食事 } */
function openMlForm(id, opts = {}) {
  const it = id ? state.myList.find(x => x.id === id) : null;
  const meal = opts.meal || null;
  if (it && it.kind === 'food') return openMlFoodForm(it);
  if (it && (it.kind === 'dish' || it.kind === 'gen')) return openMlDishForm(it);
  const kind = it ? it.kind : (opts.kind || 'prod');
  const basis = it && it.basis === '100g' ? '100g' : 'unit';
  openSheet(it ? 'マイリストを編集' : 'マイリストに登録', `
    <form id="mlForm" novalidate>
      <div class="field"><label>種類</label>
        <div class="radio-row">
          <label><input type="radio" name="kind" value="prod" ${kind === 'prod' ? 'checked' : ''}>市販品</label>
          <label><input type="radio" name="kind" value="menu" ${kind === 'menu' ? 'checked' : ''}>メニュー</label>
        </div></div>
      <div class="field"><label for="mlName">名前</label><input id="mlName" maxlength="40" value="${esc(it ? it.name : (opts.name || ''))}" placeholder="例：サラダチキン プレーン／家の豚汁"></div>
      <div class="paste-help">
        <div class="paste-btns"><button type="button" class="btn ghost small" id="mlWeb">🔍 Webで調べる</button><button type="button" class="btn ghost small" id="mlPasteBtn">📋 栄養成分表示を貼り付け</button></div>
        <div class="hint">Webページや、パッケージの写真の文字（iPhoneの写真の文字認識、Googleレンズなど）をコピーして貼り付けると、数字を読み取って下の欄に入れます</div>
        <div id="mlPasteArea" hidden>
          <textarea id="mlPaste" rows="5" placeholder="ここに貼り付け（長押し →「ペースト」）"></textarea>
          <button type="button" class="btn small block" id="mlParse">読み取る</button>
          <div id="mlParsed" class="small" style="margin-top:6px"></div>
        </div>
      </div>

      <div id="prodFields">
        <div class="field"><label>パッケージの表示</label>
          <div class="radio-row">
            <label><input type="radio" name="basis" value="unit" ${basis === 'unit' ? 'checked' : ''}>1個・1本などあたり</label>
            <label><input type="radio" name="basis" value="100g" ${basis === '100g' ? 'checked' : ''}>100gあたり</label>
          </div></div>
        <div class="field" id="unitField"><label for="mlUnit">単位</label><input id="mlUnit" maxlength="20" value="${esc(it && it.kind === 'prod' && basis === 'unit' ? it.unit : '1個')}" placeholder="例：1個、1本、1袋"></div>
        <div class="field" id="defField"><label for="mlDef">いつも食べる量（g）</label><input id="mlDef" type="number" inputmode="decimal" step="any" min="0" value="${esc(it && it.defGrams ? it.defGrams : 100)}">
          <div class="hint">タップ1回で記録するときの量です</div></div>
        <div class="label-sample">
          <div class="ls-title">見本：パッケージの栄養成分表示</div>
          <div class="ls-box"><div class="ls-head">栄養成分表示 <mark>1本（60g）あたり</mark></div>
            <div>エネルギー　　 98kcal</div><div><mark>たんぱく質　　 12.0g</mark></div><div>脂質　　　　　 3.1g</div></div>
          <div class="tiny">この例なら「1個・1本などあたり」を選び、単位「1本」、たんぱく質「12」と入れます。表示の見出しが「100gあたり」なら「100gあたり」を選んでください。</div>
        </div>
      </div>

      <div class="field"><label for="mlP" id="pLabel">たんぱく質（g）</label><input id="mlP" type="number" inputmode="decimal" step="any" min="0" value="${it ? esc(it.protein) : ''}" placeholder="例：12">
        <div class="hint" id="pHint"></div></div>
      ${showNut() ? `<div class="field"><label>カロリー・脂質・炭水化物（任意・同じ量あたり）</label>
        <div style="display:flex;gap:6px">
          <input id="mlK" type="number" inputmode="decimal" step="any" min="0" value="${it && it.kcal != null ? esc(it.kcal) : ''}" placeholder="kcal">
          <input id="mlF" type="number" inputmode="decimal" step="any" min="0" value="${it && it.fat != null ? esc(it.fat) : ''}" placeholder="脂質g">
          <input id="mlC" type="number" inputmode="decimal" step="any" min="0" value="${it && it.carb != null ? esc(it.carb) : ''}" placeholder="炭水化物g">
        </div><div class="hint">入れなくても記録できます（その分はカロリーの合計から除きます）</div></div>` : ''}
      ${showNutri() ? `<div class="field"><label>食塩相当量・食物繊維（任意・同じ量あたり）</label>
        <div style="display:flex;gap:6px">
          <input id="mlSalt" type="number" inputmode="decimal" step="any" min="0" value="${it && it.salt != null ? esc(it.salt) : ''}" placeholder="食塩相当量g">
          <input id="mlFib" type="number" inputmode="decimal" step="any" min="0" value="${it && it.fib != null ? esc(it.fib) : ''}" placeholder="食物繊維g">
        </div><div class="hint">食塩相当量はパッケージの表示に必ず書いてあります。食物繊維は書いてあれば入れてください</div></div>` : ''}
      <div class="form-err" id="mlErr" hidden></div>

      ${meal ? `<button class="btn block" type="submit" data-and="rec">登録して${mealLabel(meal)}に記録</button>
        <div class="meal-actions"><button class="btn ghost small block" type="submit" data-and="none">登録だけ</button></div>`
        : `<button class="btn block" type="submit" data-and="none">${it ? '保存' : '登録'}</button>`}
      ${it ? '<div class="meal-actions"><button type="button" class="btn danger small block" id="mlDel">マイリストから削除</button></div>' : ''}
    </form>`, sh => {
    const sync = () => {
      const k = sh.querySelector('input[name=kind]:checked').value;
      const b = sh.querySelector('input[name=basis]:checked').value;
      $('#prodFields', sh).hidden = k !== 'prod';
      $('#unitField', sh).hidden = b === '100g';
      $('#defField', sh).hidden = b !== '100g';
      const unit = $('#mlUnit', sh).value.trim() || '1個';
      $('#pLabel', sh).textContent = k === 'menu' ? '1食あたりのたんぱく質（g）' : b === '100g' ? '100gあたりのたんぱく質（g）' : `${unit}あたりのたんぱく質（g）`;
      $('#pHint', sh).textContent = k === 'menu' ? '外食の栄養表示や、レシピに書いてある1人分の値を入れてください' : '';
    };
    sh.querySelectorAll('input[name=kind],input[name=basis]').forEach(r => r.addEventListener('change', sync));
    $('#mlUnit', sh).addEventListener('input', sync);
    sync();
    // 表示していない欄（カロリー・食塩など）は、読み取った値をここに持っておいて登録時に入れる
    let extra = {};
    const setVal = (id, v) => { const el = $(id, sh); if (el && v != null) { el.value = v; el.classList.add('filled'); } return !!el; };
    const applyParsed = r => {
      extra = {};
      if (r.basis) {
        if (r.basis === '100g' || $('input[name=kind]:checked', sh).value === 'prod') sh.querySelector('input[name=kind][value=prod]').checked = true;
        sh.querySelector(`input[name=basis][value="${r.basis}"]`).checked = true;
        if (r.unit) setVal('#mlUnit', r.unit);
        if (r.defGrams) setVal('#mlDef', r.defGrams);
      }
      setVal('#mlP', r.protein);
      for (const [id, k] of [['#mlK', 'kcal'], ['#mlF', 'fat'], ['#mlC', 'carb'], ['#mlSalt', 'salt'], ['#mlFib', 'fib']]) {
        if (r[k] != null && !setVal(id, r[k])) extra[k] = r[k];
      }
      sync();
      const L = [['protein', 'たんぱく質', 'g'], ['kcal', 'エネルギー', 'kcal'], ['fat', '脂質', 'g'], ['carb', '炭水化物', 'g'], ['salt', '食塩相当量', 'g'], ['fib', '食物繊維', 'g']];
      const got = L.filter(([k]) => r[k] != null).map(([k, l, u]) => `${l} ${fmt(r[k])}${u}`);
      const miss = L.filter(([k]) => r[k] == null).map(([, l]) => l);
      const per = r.basis === '100g' ? (r.scaled ? `100gあたり（表示は${fmt(r.scaled)}gあたり → 100gあたりに直しました）` : '100gあたり') : r.unit ? `${r.unit}${r.grams ? `（${fmt(r.grams)}g）` : ''}あたり` : '何あたりか読み取れませんでした（下で選んでください）';
      $('#mlParsed', sh).innerHTML = got.length
        ? `<div class="parsed-ok"><b>読み取った値</b>：${esc(per)}<br>${esc(got.join('・'))}</div>${miss.length ? `<div class="tiny muted">読み取れなかった：${esc(miss.join('・'))}（必要なら手で入れてください）</div>` : ''}<div class="tiny" style="color:var(--accent);font-weight:700">数字がパッケージの表示と合っているか、確認してから登録してください</div>`
        : '<div class="form-err">数字を読み取れませんでした。栄養成分表示の部分だけをコピーして、もう一度お試しください。または下の欄に手で入れてください</div>';
    };
    const runParse = () => { const v = $('#mlPaste', sh).value; if (v.trim()) applyParsed(parseNutritionText(v)); };
    $('#mlParse', sh).addEventListener('click', runParse);
    $('#mlPasteBtn', sh).addEventListener('click', async () => {
      $('#mlPasteArea', sh).hidden = false;
      try {
        const txt = navigator.clipboard && navigator.clipboard.readText ? await navigator.clipboard.readText() : '';
        if (txt && txt.trim()) { $('#mlPaste', sh).value = txt; runParse(); return; }
      } catch (e) { /* 読めないときは手で貼り付けてもらう */ }
      $('#mlPaste', sh).focus();
      toast('下の欄を長押しして「ペースト」してください');
    });
    $('#mlPaste', sh).addEventListener('paste', () => setTimeout(runParse, 0));
    const draftNow = () => ({ name: $('#mlName', sh).value, kind: $('input[name=kind]:checked', sh).value, basis: $('input[name=basis]:checked', sh).value,
      unit: $('#mlUnit', sh).value, def: $('#mlDef', sh).value, p: $('#mlP', sh).value, paste: $('#mlPaste', sh).value, t: Date.now() });
    $('#mlWeb', sh).addEventListener('click', () => {
      const name = $('#mlName', sh).value.trim();
      if (!name) { toast('先に名前（商品名）を入れてください'); $('#mlName', sh).focus(); return; }
      if (!it) { state.mlDraft = draftNow(); saveState(); } // 戻ったときに入力が消えていても戻せるように
      openWebSearch(name);
    });
    // Webで調べに行った間にアプリが読み込み直されていたら、入力を戻す（1日以内）
    const dr = state.mlDraft;
    if (!it && dr && Date.now() - dr.t < 86400000 && (!opts.name || opts.name === dr.name)) {
      $('#mlName', sh).value = dr.name || '';
      sh.querySelector(`input[name=kind][value="${dr.kind}"]`).checked = true;
      sh.querySelector(`input[name=basis][value="${dr.basis}"]`).checked = true;
      $('#mlUnit', sh).value = dr.unit || '1個'; $('#mlDef', sh).value = dr.def || 100; $('#mlP', sh).value = dr.p || '';
      if (dr.paste) { $('#mlPasteArea', sh).hidden = false; $('#mlPaste', sh).value = dr.paste; }
      sync();
      toast('調べる前の入力を戻しました');
    }
    let submitter = 'none';
    sh.querySelectorAll('button[type=submit]').forEach(b => b.addEventListener('click', () => { submitter = b.dataset.and; }));
    $('#mlForm', sh).addEventListener('submit', ev => {
      ev.preventDefault();
      const err = $('#mlErr', sh);
      const showErr = m => { err.textContent = m; err.hidden = false; };
      err.hidden = true;
      const k = sh.querySelector('input[name=kind]:checked').value;
      const b = k === 'prod' ? sh.querySelector('input[name=basis]:checked').value : 'unit';
      const name = $('#mlName', sh).value.trim();
      const pRaw = $('#mlP', sh).value.trim();
      const protein = Number(pRaw);
      const unit = k === 'menu' ? '1食' : b === '100g' ? '100g' : ($('#mlUnit', sh).value.trim() || '1個');
      const defGrams = Number($('#mlDef', sh).value) || 100;
      if (!name) return showErr('名前を入れてください');
      if (pRaw === '' || !(protein >= 0)) return showErr('たんぱく質の数字を入れてください');
      // 入力ミスのチェック
      if (b === '100g' && protein > 100) return showErr('100gあたりのたんぱく質が100gを超えることはありません。数字を確認してください');
      if (k === 'prod' && b === '100g' && !(defGrams > 0)) return showErr('いつも食べる量を入れてください');
      if (k === 'prod' && b === 'unit' && protein > 80 && !confirm(`${unit}あたり ${protein}g はかなり多い値です。「100gあたり」の表示ではありませんか？\nこのまま登録する場合は OK を押してください。`)) return;
      if (k === 'menu' && protein > 100 && !confirm(`1食あたり ${protein}g はかなり多い値です。このまま登録しますか？`)) return;
      const data = { kind: k, name, protein, basis: b, unit, defGrams: b === '100g' ? defGrams : undefined };
      if ($('#mlK', sh)) {
        const nv = id => { const x = $(id, sh).value.trim(); return x === '' ? null : Number(x); };
        Object.assign(data, { kcal: nv('#mlK'), fat: nv('#mlF'), carb: nv('#mlC') });
        if (data.kcal == null) { data.fat = null; data.carb = null; }
      }
      if ($('#mlSalt', sh)) {
        const nv = id => { const x = $(id, sh).value.trim(); return x === '' ? null : Number(x); };
        Object.assign(data, { salt: nv('#mlSalt'), fib: nv('#mlFib') });
      }
      for (const [k, v] of Object.entries(extra)) if (data[k] === undefined) data[k] = v; // 表示していない欄で読み取った値
      if (data.kcal == null && (data.fat != null || data.carb != null)) { data.fat = null; data.carb = null; }
      delete state.mlDraft;
      let target;
      if (it) { Object.assign(it, data); target = it; }
      else { target = Object.assign({ id: uid() }, data); state.myList.push(target); }
      saveState();
      if (meal && submitter === 'rec') {
        const e = mlEntry(target, meal);
        addEntry(viewDate, e);
        toast(`${name} ${fmt(e.protein)}g を${mealLabel(meal)}に記録しました`);
        closeSheet(); render();
      } else if (meal) {
        toast('マイリストに登録しました');
        openAdd(meal); sheetCtx.mode = 'ml'; setSeg('ml'); renderResults();
      } else {
        toast(it ? '保存しました' : '登録しました');
        closeSheet(); render();
      }
    });
    const del = $('#mlDel', sh);
    if (del) del.addEventListener('click', () => deleteMl(it));
  });
}
function openMlFoodForm(it) {
  const f = foodByCode.get(it.code);
  openSheet('マイリストを編集', `
    <form id="mlFoodForm">
      <div class="small muted">${esc(f ? f.name : '')}</div>
      <div class="field" style="margin-top:8px"><label for="mfName">名前</label><input id="mfName" maxlength="40" required value="${esc(it.name)}"></div>
      <div class="field"><label for="mfG">量（g）</label><input id="mfG" type="number" inputmode="decimal" step="any" min="0" required value="${esc(it.grams)}"></div>
      <button class="btn block" type="submit">保存</button>
      <div class="meal-actions"><button type="button" class="btn danger small block" id="mlDel">マイリストから削除</button></div>
    </form>`, sh => {
    $('#mlFoodForm', sh).addEventListener('submit', ev => {
      ev.preventDefault();
      const g = Number($('#mfG', sh).value);
      const name = $('#mfName', sh).value.trim();
      if (!name || !(g > 0)) return;
      if (Math.abs(g - it.grams) > 0.05) Object.assign(it, { amode: 'g', desc: `${fmt(g)}g`, ulabel: null, count: null, raw: null });
      Object.assign(it, { name, grams: g });
      saveState(); toast('保存しました'); closeSheet(); render();
    });
    $('#mlDel', sh).addEventListener('click', () => deleteMl(it));
  });
}
function deleteMl(it) {
  if (!confirm(`「${it.name}」をマイリストから削除しますか？（これまでの記録は残ります）`)) return;
  state.myList = state.myList.filter(x => x.id !== it.id);
  saveState(); closeSheet(); render();
}

/* マイリストの市販品・メニューや、その記録の量を入れる。item = {kind, id, name, unit, protein, basis} */
function itemFromEntry(e) {
  if (e.kind === 'dish') { const d = DISHES.find(x => x.id === e.refId); if (d && d.gu) return guDishItem(d, e.gu || d.guDef, guOpt(e)); }
  const it = { kind: e.kind || 'my', id: e.refId || e.myId, name: e.name, unit: e.unit || '1食', protein: e.perUnit, basis: e.basis || 'unit', kcal: e.perKcal ?? null, fat: e.perFat ?? null, carb: e.perCarb ?? null };
  // 以前の記録で1単位あたりのカロリーが無いものは、今のデータから補う
  if (it.kcal == null) {
    const src = it.kind === 'dish' ? (() => { const d = DISHES.find(x => x.id === it.id); return d && dishItem(d); })()
      : it.kind === 'gen' ? GENERIC_ITEMS.find(x => x.id === it.id)
      : e.mlId ? (() => { const m = state.myList.find(x => x.id === e.mlId); return m && m.kind !== 'food' ? mlItem(m) : null; })() : null;
    if (src) Object.assign(it, { kcal: src.kcal ?? null, fat: src.fat ?? null, carb: src.carb ?? null });
  }
  return it;
}
/* 修正画面の目印：何の記録を直しているか */
function editTag(e) {
  return `<div class="edit-tag">✎ ${esc(dateLabel(viewDate))}・${esc(mealLabel(e.meal))}の記録を修正しています<div class="tiny muted">今の量：${esc(entryAmountLabel(e))}・たんぱく質 ${fmt(e.protein)}g</div></div>`;
}
/* opts.reg：設定の「メニューを登録」から（記録せずマイリストに登録）／opts.mlSave：マイリストの内容を直す（そのマイリストのid） */
function openItemAmount(item, entry, defVal, mlId, opts = {}) {
  const is100 = item.basis === '100g';
  const meal = entry ? entry.meal : (sheetCtx && sheetCtx.meal) || guessMeal();
  const val = entry ? (is100 ? entry.grams : entry.qty) : (defVal || (is100 ? 100 : 1));
  const reg = !!opts.reg, mlSave = opts.mlSave || null;
  sheetCtx = { meal, item, val, editing: entry || null, mlId: entry ? entry.mlId : mlId, reg, mlSave };
  const chips = item.chips || (is100 ? [50, 100, 150, 200] : [0.5, 1, 1.5, 2, 3]);
  const mainLabel = reg ? 'マイリストに登録' : mlSave ? 'マイリストを更新' : entry ? '修正する' : '記録する';
  const star = !reg && !mlSave && !sheetCtx.mlId;
  openSheet(esc(item.title || (entry ? dispName(entry.name).name : item.name)), `
    ${reg || mlSave ? '<div class="small muted" style="margin-bottom:4px">いつも食べる量と内容にして登録します。記録はしません</div>' : ''}
    ${item.kind === 'gen' ? '' : `<div class="tiny muted" id="perUnit">${is100 ? '100g' : esc(item.unit)}あたり たんぱく質 ${fmt(item.protein)}g</div>`}
    ${reg || mlSave ? '' : `<div class="meal-pick">${MEALS.map(([mm, l]) => `<button class="chip ${mm === meal ? 'on' : ''}" data-meal="${mm}">${l}</button>`).join('')}</div>`}
    <div class="amount-box"><input id="qty" type="number" inputmode="decimal" min="0" step="any" value="${fmt(val)}"><span class="u">${is100 ? 'g' : '× ' + esc(item.unit)}</span></div>
    <div class="chips">${chips.map(q => `<button class="chip" data-q="${q}">${q}${is100 ? 'g' : ''}</button>`).join('')}</div>
    <div id="guBox">${item.sel ? guBoxHtml() : ''}</div>
    ${item.kind === 'gen' ? `<div class="note">${esc((GENERIC_ITEMS.find(g => g.id === item.id) || {}).note || '')}</div>` : ''}
    ${item.kind === 'dish' ? `<div class="note" id="dishNote">${esc(dishNote(item.id, item))}</div>` : ''}
    <div class="result"><span>たんぱく質</span><b id="calc">0g</b></div>
    <button class="btn block" id="${reg ? 'regItem' : mlSave ? 'saveMlItem' : 'saveMy'}">${mainLabel}</button>
    ${star ? '<div class="meal-actions"><button class="btn ghost small block" id="starItem">☆ この内容でマイリストへ</button></div>' : ''}
    ${entry ? '<div class="meal-actions"><button class="btn danger small block" id="delEntry">この記録を削除</button></div>' : ''}
  `, sh => {
    const qty = $('#qty', sh);
    const upd = () => {
      const item = sheetCtx.item; // 具を変えると item が作り直されるので、毎回 sheetCtx から
      $('#calc', sh).textContent = `${fmt(itemProtein(item, sheetCtx.val))}g`;
      if (showNut() && item.kcal != null) $('#calc', sh).insertAdjacentHTML('beforeend', `<span class="tiny muted" style="font-weight:400">　${itemNut(item, sheetCtx.val).kcal}kcal</span>`);
      const ok = Number(sheetCtx.val) > 0;
      sh.querySelectorAll('#saveMy, #regItem, #saveMlItem, #starItem').forEach(x => { x.disabled = !ok; });
    };
    qty.addEventListener('input', () => {
      sheetCtx.val = Number(qty.value) || 0; upd();
      if (sheetCtx.item.sel && sheetCtx.val > 0) renderGuBox(); // 具の量は「かけたあと」で見せるので出し直す
    });
    sheetCtx.upd = upd;
    upd();
    bindGuBox();
  }, { editing: !!entry });
}
/* 具のボタン。guGroups があれば「肉」「魚介」などの見出しごとに分けて並べる */
function guChipsHtml(d, sel) {
  const chip = ([k, l]) => `<button class="chip ${sel.includes(k) ? 'on' : ''}" data-gu="${k}">${l}</button>`;
  if (!d.guGroups) return `<div class="gu-head">具（タップで選ぶ）</div><div class="chips gu">${d.gu.map(chip).join('')}</div>`;
  return `<div class="gu-head">具（タップで選ぶ）</div>` + d.guGroups.map(([title, keys]) =>
    `<div class="gu-sub">${esc(title)}</div><div class="chips gu">${d.gu.filter(g => keys.includes(g[0])).map(chip).join('')}</div>`).join('');
}
/* 具の欄：味 → 具のボタン → 選んだ具と量の一覧（タップで量を直す） */
function guBoxHtml() {
  const c = sheetCtx, it = c.item;
  if (!it || !it.sel) return '';
  const d = DISHES.find(x => x.id === it.id);
  let h = '';
  if (d.dashi) {
    const cur = d.dashi.find(x => x[0] === it.dashi);
    h += `<div class="gu-sec"><div class="gu-sec-h">味（だし・たれ）<span>${esc(cur ? cur[1] : '')}</span></div>
      <div class="chips gu">${d.dashi.map(([k, l]) => `<button class="chip ${k === it.dashi ? 'on' : ''}" data-dashi="${k}">${esc(l)}</button>`).join('')}</div></div>`;
  }
  h += `<div class="gu-sec"><div class="gu-sec-h">具<span>${it.sel.length}品えらんでいます</span></div>${guChipsHtml(d, it.sel).replace('<div class="gu-head">具（タップで選ぶ）</div>', '<div class="tiny muted" style="margin:-2px 0 4px">タップで入れる・外す</div>')}</div>`;
  const gus = d.gu.filter(g => it.sel.includes(g[0]));
  if (gus.length) {
    const v = Number(c.val) || 1;
    const line = g => `<button class="gu-line ${c.guEdit === g[0] ? 'open' : ''}" data-gued="${g[0]}"><span class="gu-name">${esc(g[1])}</span><b class="gu-amt" id="gua-${g[0]}">${esc(guAmtText(g, it.ga, v))}</b><span class="gu-arrow">${c.guEdit === g[0] ? '閉じる' : '直す'}</span></button>` +
      (c.guEdit === g[0] ? guEditorHtml(g, it.ga, v) : '');
    // 「肉」「魚介」などの見出しごとに分けて並べる
    const groups = d.guGroups ? d.guGroups.map(([t, keys]) => [t, gus.filter(g => keys.includes(g[0]))]).filter(([, l]) => l.length) : [['', gus]];
    h += `<div class="gu-sec gu-sec-amt"><div class="gu-sec-h">量<span>${esc(fmt(v) + d.unit.replace(/^1/, ''))}分・タップで直せます</span></div>` +
      groups.map(([t, l]) => `${t ? `<div class="gu-grp">${esc(t)}</div>` : ''}<div class="gu-list">${l.map(line).join('')}</div>`).join('') + '</div>';
  }
  return h;
}
function guAmtText(g, ga, v) {
  const sp = guSpec(g), a = guAmt(g, ga) * v, grams = guGrams(g, ga) * v;
  if (sp.t === 'g') return `${fmt(a)}g`;
  if (sp.t === 'pc') return `${fmt(a)}${sp.u}（${fmt(grams)}g）`;
  const lv = GU_LVL.find(x => x[0] === guAmt(g, ga));
  return `${lv ? lv[1] : '×' + fmt(guAmt(g, ga))}（${fmt(grams)}g）`;
}
function guEditorHtml(g, ga, v) {
  const sp = guSpec(g), a = guAmt(g, ga);
  if (sp.t === 'lvl') return `<div class="gu-ed"><div class="chips">${GU_LVL.map(([m, l]) => `<button class="chip ${m === a ? 'on' : ''}" data-gulv="${m}">${l}</button>`).join('')}</div></div>`;
  if (sp.t === 'pc') return `<div class="gu-ed">
    <div class="gu-cnt"><button class="btn ghost small" data-gupc="-1" aria-label="減らす">−</button><b id="guCnt">${fmt(a * v)}</b><span>${esc(sp.u)}</span><button class="btn ghost small" data-gupc="1" aria-label="増やす">＋</button></div>
    <label class="gu-gin">gで入れる <input id="guIn" type="number" inputmode="decimal" min="0" step="any" value="${fmt(a * v * sp.w)}"> g</label>
    <div class="tiny muted">1${esc(sp.u)}＝約${fmt(sp.w)}gの目安</div></div>`;
  const base = g[3];
  const set = base <= 30 ? [10, 20, 30, 50, 75] : base >= 150 ? [100, 150, 200, 250, 300] : [30, 50, 80, 100, 150, 200];
  return `<div class="gu-ed">
    <label class="gu-gin"><input id="guIn" type="number" inputmode="decimal" min="0" step="any" value="${fmt(a * v)}"> g</label>
    <div class="chips">${set.map(x => `<button class="chip" data-gug="${x}">${x}g</button>`).join('')}</div></div>`;
}
/* 具・量・味が変わったら計算し直す（rerender：具の欄も出し直す） */
function guRecalc(rerender) {
  const it = sheetCtx.item;
  const d = DISHES.find(x => x.id === it.id);
  sheetCtx.item = guDishItem(d, it.sel, { ga: it.ga, dashi: it.dashi });
  const pu = $('#perUnit'); if (pu) pu.textContent = `${sheetCtx.item.unit}あたり たんぱく質 ${fmt(sheetCtx.item.protein)}g`;
  const dn = $('#dishNote'); if (dn) dn.textContent = dishNote(d.id, sheetCtx.item);
  if (rerender) renderGuBox();
  if (sheetCtx.upd) sheetCtx.upd();
}
function renderGuBox() {
  const box = $('#guBox');
  if (!box) return;
  box.innerHTML = guBoxHtml();
  bindGuBox();
}
function bindGuBox() {
  const inp = $('#guIn');
  if (!inp) return;
  inp.addEventListener('input', () => {
    const c = sheetCtx, it = c.item, k = c.guEdit;
    const d = DISHES.find(x => x.id === it.id);
    const g = d.gu.find(x => x[0] === k);
    const x = Number(inp.value), v = Number(c.val) || 1;
    if (!g || !(x > 0)) return;
    const sp = guSpec(g);
    it.ga = Object.assign({}, it.ga, { [k]: sp.t === 'pc' ? x / v / sp.w : x / v });
    guRecalc(false);
    const t = $('#gua-' + k); if (t) t.textContent = guAmtText(g, sheetCtx.item.ga, v);
    const cnt = $('#guCnt'); if (cnt) cnt.textContent = fmt(guAmt(g, sheetCtx.item.ga) * v);
  });
}
function itemProtein(item, val) {
  const v = Number(val) || 0;
  return r1(item.basis === '100g' ? item.protein * v / 100 : item.protein * v);
}

/* ---------- カロリー・PFC（脂質・炭水化物） ----------
   記録したときに kcal・脂質・炭水化物も保存する（あとで成分表や料理を見直しても過去の記録は変わらない）。
   以前の記録（保存していないもの）は、今のデータから計算して表示する。マイリストで未入力のものは「不明」 */
function nutOf(src, factor) {
  if (!src || src.kcal == null) return { kcal: null, fat: null, carb: null };
  return { kcal: Math.round(src.kcal * factor), fat: src.fat == null ? null : r1(src.fat * factor), carb: src.carb == null ? null : r1(src.carb * factor) };
}
function foodNut(f, grams) { return nutOf(f, (Number(grams) || 0) / 100); }
function itemNut(item, val) { const v = Number(val) || 0; return nutOf(item, item.basis === '100g' ? v / 100 : v); }
function entryNut(e) {
  if (e.kcal !== undefined) return { kcal: e.kcal, fat: e.fat ?? null, carb: e.carb ?? null };
  if (e.code && foodByCode.has(e.code)) return foodNut(foodByCode.get(e.code), e.grams);
  if (e.kind === 'dish') { const d = DISHES.find(x => x.id === e.refId); const it = d && dishItem(d, d.gu ? (e.gu || d.guDef) : undefined, guOpt(e)); if (it) return itemNut(it, e.qty); }
  if (e.kind === 'gen') { const g = GENERIC_ITEMS.find(x => x.id === e.refId); if (g) return itemNut(g, e.grams); }
  if (e.mlId) { const m = state.myList.find(x => x.id === e.mlId); if (m && m.kcal != null && m.kind !== 'food') return itemNut(mlItem(m), m.basis === '100g' ? e.grams : e.qty); }
  return { kcal: null, fat: null, carb: null };
}
function sumNut(list) {
  let kcal = 0, fat = 0, carb = 0, p = 0, unknown = 0;
  for (const e of list) {
    const n = entryNut(e);
    if (n.kcal == null) { unknown++; continue; }
    kcal += n.kcal; fat += n.fat || 0; carb += n.carb || 0; p += Number(e.protein) || 0;
  }
  return { kcal: Math.round(kcal), fat: r1(fat), carb: r1(carb), p: r1(p), unknown };
}
const showNut = () => !!state.showPFC;
// 今日の画面：合計 kcal と PFC の割合（エネルギー比は P・C 4kcal/g、F 9kcal/g で計算）
function pfcHtml(list, t) {
  const n = sumNut(list);
  const eP = n.p * 4, eF = n.fat * 9, eC = n.carb * 4, eT = eP + eF + eC;
  const pct = x => eT > 0 ? Math.round(x / eT * 100) : 0;
  const [pLo, pHi] = String((t && t.goalPct) || '13〜20').split('〜').map(Number);
  const segs = [['P', pct(eP), pLo, pHi, 'var(--primary)'], ['F', pct(eF), 20, 30, 'var(--accent)'], ['C', pct(eC), 50, 65, 'var(--bar-soft)']];
  const bar = eT > 0 ? segs.map(([k, v, lo, hi, col]) => `<span style="width:${v}%;background:${col};display:flex;align-items:center;justify-content:center;color:#fff;font-size:.72rem;font-weight:700;min-width:${v ? 28 : 0}px;overflow:hidden">${v ? k + v + '%' : ''}</span>`).join('') : '';
  // P（たんぱく質）が上限を超えたときは警告にしない（記録漏れで高めに出やすいため、中立の一言だけ）
  const off = eT > 0 ? segs.filter(([k, v, lo, hi]) => v < lo || (k !== 'P' && v > hi)).map(([k, v, lo]) => `${k}${v < lo ? '少なめ' : '多め'}`) : [];
  const pOver = eT > 0 && pct(eP) > pHi;
  return `<div style="margin-top:12px;padding-top:10px;border-top:1px dashed var(--line)">
    <div style="display:flex;justify-content:space-between;align-items:baseline;gap:8px;flex-wrap:wrap">
      <span><b style="font-size:1.15rem">${n.kcal.toLocaleString()}</b><span class="small muted"> kcal${t && t.eer ? `　／ 目安 約${t.eer.toLocaleString()}kcal` : ''}</span></span>
      <span class="small">P ${fmt(n.p)}g　F ${fmt(n.fat)}g　C ${fmt(n.carb)}g</span>
    </div>
    ${eT > 0 ? `<div style="display:flex;height:22px;border-radius:11px;overflow:hidden;margin:6px 0 4px;background:var(--track)">${bar}</div>` : ''}
    <div class="tiny muted">目安 P${pLo}〜${pHi}%・F20〜30%・C50〜65%${off.length ? `　<b style="color:var(--accent)">${off.join('・')}</b>` : ''}${pOver ? `<br>Pが目標の上限（${pHi}%）を超えています。ごはんや油などの記録が抜けていても高めに出ます` : ''}${n.unknown ? `<br>カロリー不明の記録${n.unknown}件は除いています（マイリストで未入力など）` : ''}</div>
  </div>`;
}

/* ---------- ほかの栄養素（設定でオンにしたときだけ。nutri.json を読む） ----------
   値は成分表の可食部100gあたり。料理は材料から計算。調理による減少（ゆでたときのビタミンなど）は含まない。
   公式値の市販品・外食、一般的な目安は不明（マイリストの市販品・メニューは、入れていれば食塩・食物繊維だけ使う） */
const NUTRI = [ // [キー, 名前, 単位, 小数, 区分]
  ['salt', '食塩相当量', 'g', 1, 'main'], ['fib', '食物繊維', 'g', 1, 'main'], ['ca', 'カルシウム', 'mg', 0, 'main'], ['fe', '鉄', 'mg', 1, 'main'],
  ['va', 'ビタミンA', 'μg', 0, 'vit'], ['vd', 'ビタミンD', 'μg', 1, 'vit'], ['ve', 'ビタミンE', 'mg', 1, 'vit'], ['vk', 'ビタミンK', 'μg', 0, 'vit'],
  ['b1', 'ビタミンB1', 'mg', 2, 'vit'], ['b2', 'ビタミンB2', 'mg', 2, 'vit'], ['ne', 'ナイアシン', 'mgNE', 1, 'vit'], ['b6', 'ビタミンB6', 'mg', 2, 'vit'],
  ['b12', 'ビタミンB12', 'μg', 1, 'vit'], ['fol', '葉酸', 'μg', 0, 'vit'], ['pant', 'パントテン酸', 'mg', 1, 'vit'], ['vc', 'ビタミンC', 'mg', 0, 'vit'],
];
/* 食事摂取基準（2025年版）の値。年齢区分は DRI.brackets と同じ（1〜2歳 … 75歳以上）
   t：rda 推奨量／ai 目安量／dgMin 目標量（以上）／dgMax 目標量（未満）。add：妊婦・授乳婦（付加量は +、それ以外はその値） */
const NUTRI_REF = {
  salt: { t: 'dgMax', m: [3.0, 3.5, 4.5, 5.0, 6.0, 7.0, 7.5, 7.5, 7.5, 7.5, 7.5, 7.5], f: [2.5, 3.5, 4.5, 5.0, 6.0, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5, 6.5], fixed: { preg1: 6.5, preg2: 6.5, preg3: 6.5, lact: 6.5 } },
  fib: { t: 'dgMin', m: [null, 8, 10, 11, 13, 17, 19, 20, 22, 22, 21, 20], f: [null, 8, 9, 11, 13, 16, 18, 18, 18, 18, 18, 17], fixed: { preg1: 18, preg2: 18, preg3: 18, lact: 18 } },
  ca: { t: 'rda', m: [450, 600, 600, 650, 700, 1000, 800, 800, 750, 750, 750, 750], f: [400, 550, 550, 750, 750, 800, 650, 650, 650, 650, 650, 600] },
  fe: { t: 'rda', m: [4.0, 5.0, 6.0, 7.5, 9.5, 9.0, 9.0, 7.0, 7.5, 7.0, 7.0, 6.5], f: [4.0, 5.0, 6.0, 8.0, 9.0, 8.0, 6.5, 6.0, 6.0, 6.0, 6.0, 5.5],
    fMens: [null, null, null, null, 12.5, 12.5, 11.0, 10.0, 10.5, 10.5, null, null], add: { preg1: 2.5, preg2: 8.5, preg3: 8.5, lact: 2.0 } },
  va: { t: 'rda', m: [400, 500, 500, 500, 600, 800, 900, 850, 900, 900, 850, 800], f: [350, 500, 500, 500, 600, 700, 650, 650, 700, 700, 700, 650], add: { preg3: 80, lact: 450 } },
  vd: { t: 'ai', m: [3.5, 4.5, 5.5, 6.5, 8.0, 9.0, 9.0, 9.0, 9.0, 9.0, 9.0, 9.0], f: [3.5, 4.5, 5.5, 6.5, 8.0, 9.0, 9.0, 9.0, 9.0, 9.0, 9.0, 9.0], fixed: { preg1: 9.0, preg2: 9.0, preg3: 9.0, lact: 9.0 } },
  ve: { t: 'ai', m: [3.0, 4.0, 4.5, 5.0, 5.0, 6.5, 7.0, 6.5, 6.5, 6.5, 7.5, 7.0], f: [3.0, 4.0, 4.0, 5.0, 5.5, 6.0, 6.0, 5.0, 6.0, 6.0, 7.0, 6.0], fixed: { preg1: 5.5, preg2: 5.5, preg3: 5.5, lact: 5.5 } },
  vk: { t: 'ai', m: [50, 60, 80, 90, 110, 140, 150, 150, 150, 150, 150, 150], f: [60, 70, 90, 110, 130, 150, 150, 150, 150, 150, 150, 150], fixed: { preg1: 150, preg2: 150, preg3: 150, lact: 150 } },
  b1: { t: 'rda', m: [0.4, 0.5, 0.7, 0.8, 0.9, 1.1, 1.2, 1.1, 1.2, 1.1, 1.0, 1.0], f: [0.4, 0.5, 0.6, 0.7, 0.9, 1.0, 1.0, 0.8, 0.9, 0.8, 0.8, 0.7], add: { preg1: 0.2, preg2: 0.2, preg3: 0.2, lact: 0.2 } },
  b2: { t: 'rda', m: [0.6, 0.8, 0.9, 1.1, 1.4, 1.6, 1.7, 1.6, 1.7, 1.6, 1.4, 1.4], f: [0.5, 0.8, 0.9, 1.0, 1.3, 1.4, 1.4, 1.2, 1.2, 1.2, 1.1, 1.1], add: { preg1: 0.3, preg2: 0.3, preg3: 0.3, lact: 0.6 } },
  ne: { t: 'rda', m: [6, 8, 9, 11, 13, 15, 16, 15, 16, 15, 14, 13], f: [5, 7, 8, 10, 12, 14, 13, 11, 12, 11, 11, 10], add: { lact: 3 } },
  b6: { t: 'rda', m: [0.5, 0.6, 0.7, 0.9, 1.0, 1.4, 1.5, 1.5, 1.5, 1.5, 1.4, 1.4], f: [0.5, 0.6, 0.7, 0.9, 1.2, 1.3, 1.3, 1.2, 1.2, 1.2, 1.2, 1.2], add: { preg1: 0.2, preg2: 0.2, preg3: 0.2, lact: 0.3 } },
  b12: { t: 'ai', m: [1.5, 1.5, 2.0, 2.5, 3.0, 4.0, 4.0, 4.0, 4.0, 4.0, 4.0, 4.0], f: [1.5, 1.5, 2.0, 2.5, 3.0, 4.0, 4.0, 4.0, 4.0, 4.0, 4.0, 4.0], fixed: { preg1: 4.0, preg2: 4.0, preg3: 4.0, lact: 4.0 } },
  fol: { t: 'rda', m: [90, 100, 130, 150, 180, 230, 240, 240, 240, 240, 240, 240], f: [90, 100, 130, 150, 180, 230, 240, 240, 240, 240, 240, 240], add: { preg2: 240, preg3: 240, lact: 100 } },
  pant: { t: 'ai', m: [3, 4, 5, 6, 6, 7, 7, 6, 6, 6, 6, 6], f: [3, 4, 5, 6, 6, 6, 6, 5, 5, 5, 5, 5], fixed: { preg1: 5, preg2: 5, preg3: 5, lact: 6 } },
  vc: { t: 'rda', m: [35, 40, 50, 60, 70, 90, 100, 100, 100, 100, 100, 100], f: [35, 40, 50, 60, 70, 90, 100, 100, 100, 100, 100, 100], add: { preg1: 10, preg2: 10, preg3: 10, lact: 45 } },
};
const NUTRI_T_LABEL = { rda: '推奨量', ai: '目安量', dgMin: '目標量', dgMax: '目標量' };
const showNutri = () => !!state.showNutri;
let nutriByCode = null, nutriKeys = null, nutriLoading = false;
async function loadNutri() {
  if (nutriByCode || nutriLoading) return;
  nutriLoading = true;
  try {
    const res = await fetch('nutri.json');
    const data = await res.json();
    nutriKeys = data.keys;
    nutriByCode = new Map(Object.entries(data.foods));
    render();
  } catch (e) {
    toast('栄養素のデータを読み込めませんでした（通信できるときにもう一度開いてください）');
  } finally { nutriLoading = false; }
}
/* 食品番号・g の並びから、栄養素ごとの量（1つでも値がない材料があれば その栄養素は null） */
function nutriOfItems(items, factor = 1) {
  const out = NUTRI.map(() => 0);
  for (const [code, g] of items) {
    const v = nutriByCode.get(code);
    NUTRI.forEach(([k], i) => {
      if (out[i] == null) return;
      let x = v ? v[nutriKeys.indexOf(k)] : null;
      if (x == null && v && /^1[67]/.test(code)) x = 0; // 調味料・だし・飲料の「－」（未測定）は、ほぼ0とみなす
      out[i] = x == null ? null : out[i] + x * g / 100 * factor;
    });
  }
  return out;
}
/* 1件の記録の栄養素（わからないものは null） */
function entryNutri(e) {
  const none = NUTRI.map(() => null);
  if (!nutriByCode) return none;
  if (e.code) return nutriOfItems([[e.code, Number(e.grams) || 0]]);
  if (e.kind === 'dish') {
    const d = DISHES.find(x => x.id === e.refId);
    if (!d) return none;
    if (d.fixed != null) { // 公式値：表に載っている栄養素だけ（KFCなど）
      const q = Number(e.qty) || 0;
      return NUTRI.map(([k]) => d.nut && d.nut[k] != null ? d.nut[k] * q : null);
    }
    const items = d.gu ? (guDishItem(d, e.gu || d.guDef, guOpt(e)) || {}).guItems : d.items;
    return items ? nutriOfItems(items, Number(e.qty) || 0) : none;
  }
  if (e.mlId) { // マイリストの市販品・メニュー：入れていれば食塩・食物繊維
    const m = state.myList.find(x => x.id === e.mlId);
    if (!m || (m.kind !== 'prod' && m.kind !== 'menu')) return none;
    const f = m.basis === '100g' ? (Number(e.grams) || 0) / 100 : (Number(e.qty) || 0);
    return NUTRI.map(([k]) => (k === 'salt' || k === 'fib') && m[k] != null ? m[k] * f : null);
  }
  return none;
}
/* 記録の並びの合計。unknown[i]：その栄養素がわからない記録の数 */
function sumNutri(list) {
  const total = NUTRI.map(() => 0), unknown = NUTRI.map(() => 0);
  for (const e of list) entryNutri(e).forEach((x, i) => { if (x == null) unknown[i]++; else total[i] += x; });
  return { total, unknown, n: list.length };
}
/* 基準の値（その人の年齢・性別・妊娠授乳） */
function nutriRef(k, p) {
  const r = NUTRI_REF[k];
  if (!p || !p.age || p.age < 1) return null;
  const bi = DRI.brackets.findIndex(([lo, hi]) => p.age >= lo && p.age <= hi);
  if (bi < 0) return null;
  const sex = p.sex === 'm' ? 'm' : 'f';
  let v = r[sex][bi];
  const st = sex === 'f' ? p.status || 'none' : 'none';
  if (st !== 'none') {
    if (r.fixed && r.fixed[st] != null) v = r.fixed[st];
    else if (r.add && r.add[st] != null && v != null) v = r1(v + r.add[st]);
  }
  if (v == null) return null;
  const mens = k === 'fe' && sex === 'f' && st === 'none' && r.fMens[bi] != null ? r.fMens[bi] : null;
  return { v, t: r.t, mens };
}
function nfmt(x, d) { return x == null ? '-' : d === 0 ? String(Math.round(x)) : (Math.round(x * 10 ** d) / 10 ** d).toFixed(d).replace(/\.?0+$/, '') || '0'; }
function nutriRefText(ref, unit, d) {
  if (!ref) return '';
  const lab = NUTRI_T_LABEL[ref.t];
  const v = `${nfmt(ref.v, d)}${unit}`;
  return ref.t === 'dgMax' ? `${lab} ${v}未満` : ref.t === 'dgMin' ? `${lab} ${v}以上` : `${lab} ${v}${ref.mens ? `（月経ありは${nfmt(ref.mens, d)}${unit}）` : ''}`;
}
/* 1行：名前・量・基準・棒（基準に対する割合。食塩は目標量に対して） */
function nutriRow(i, val, unk, p, mode) {
  const [k, name, unit, d] = NUTRI[i];
  const ref = nutriRef(k, p);
  const pct = ref && val != null ? Math.min(100, (val / ref.v) * 100) : 0;
  const over = ref && ref.t === 'dgMax' && val >= ref.v;
  return `<button class="nrow" data-nbd="${i}" data-nbm="${mode || 'day'}">
    <div class="nrow-top"><span>${name} <span class="nrow-go">›</span></span><b>${nfmt(val, d)}${unit}</b></div>
    ${ref ? `<div class="nbar"><span style="width:${pct}%;${over ? 'background:var(--accent)' : ''}"></span></div>` : ''}
    <div class="tiny muted">${esc(nutriRefText(ref, unit, d))}${unk ? `${ref ? '・' : ''}不明${unk}件を除く` : ''}</div>
  </button>`;
}
/* 今日の画面：主な4つ＋「詳細」 */
function nutriTodayHtml(list) {
  if (!nutriByCode) return `<div class="tiny muted" style="margin-top:10px">栄養素のデータを読み込み中…</div>`;
  if (!list.length) return '';
  const s = sumNutri(list);
  return `<div style="margin-top:12px;padding-top:10px;border-top:1px dashed var(--line)">
    <div class="small" style="font-weight:700;margin-bottom:4px">ほかの栄養素（目安）</div>
    <div class="ngrid">${NUTRI.map((x, i) => x[4] === 'main' ? nutriRow(i, s.total[i], s.unknown[i], state.profile, 'day') : '').join('')}</div>
    <button class="btn ghost small block" data-nutri="day" style="margin-top:6px">詳細（ビタミンも見る）</button>
  </div>`;
}
/* 栄養素ごとの内訳：どの食べ物から何をとったか（多い順）。週は同じ食べ物をまとめて7日分の合計 */
let nutriCtx = null; // 詳細シートから開いたとき、閉じると詳細シートに戻る
function nutriDays(mode) {
  if (mode !== 'week') return [viewDate];
  const days = [];
  for (let i = 6; i >= 0; i--) { const d = addDays(todayStr(), -i); if (dayEntries(d).length) days.push(d); }
  return days;
}
function openNutriBreakdown(i, mode) {
  const [k, name, unit, dg] = NUTRI[i];
  const days = nutriDays(mode);
  const rows = new Map(), unknown = new Map();
  for (const day of days) for (const e of dayEntries(day)) {
    const v = entryNutri(e)[i];
    const nm = dispName(e.name).name;
    if (v == null) { unknown.set(nm, (unknown.get(nm) || 0) + 1); continue; }
    const key = mode === 'week' ? nm : e.id;
    const r = rows.get(key) || { name: nm, amt: mode === 'week' ? '' : entryAmountLabel(e), meal: mode === 'week' ? '' : (MEALS.find(m => m[0] === e.meal) || [])[1], v: 0, n: 0 };
    r.v += v; r.n++;
    rows.set(key, r);
  }
  const list = [...rows.values()].filter(r => r.v > 0).sort((a, b) => b.v - a.v);
  const zero = [...rows.values()].filter(r => !(r.v > 0));
  const total = list.reduce((a, r) => a + r.v, 0);
  const sub = mode === 'week' ? `直近7日（記録のある${days.length}日）の合計です。多い順` : `${dateLabel(viewDate)}の記録です。多い順`;
  openSheet(esc(`${name}の内訳`), `
    <div class="small muted">${esc(sub)}</div>
    ${list.length ? `<div class="nbd-list">${list.map(r => `<div class="nbd-row">
        <div class="nbd-name"><div>${esc(r.name)}</div><div class="tiny muted">${esc([r.meal, r.amt, mode === 'week' && r.n > 1 ? r.n + '回' : ''].filter(Boolean).join('・'))}</div></div>
        <div class="nbd-v"><b>${nfmt(r.v, dg)}${unit}</b><div class="nbd-bar"><span style="width:${Math.max(3, (r.v / list[0].v) * 100)}%"></span></div><div class="tiny muted">${total > 0 ? Math.round(r.v / total * 100) : 0}%</div></div>
      </div>`).join('')}</div>` : `<div class="empty small">${esc(name)}をとった記録はありません</div>`}
    ${zero.length ? `<div class="tiny muted" style="margin-top:8px">ほぼ含まない：${esc(zero.map(r => r.name).join('、'))}</div>` : ''}
    ${unknown.size ? `<div class="tiny muted" style="margin-top:6px">値がわからない（合計に入っていない）：${esc([...unknown.entries()].map(([n, c]) => c > 1 ? `${n}（${c}回）` : n).join('、'))}</div>` : ''}
  `, null, { tall: true });
}

/* 詳細シート：その日 or 直近7日の平均 */
function openNutriSheet(mode) {
  const p = state.profile;
  let s, title, sub;
  if (mode === 'week') {
    const days = [];
    for (let i = 6; i >= 0; i--) { const d = addDays(todayStr(), -i); if (dayEntries(d).length) days.push(d); }
    const all = days.flatMap(d => dayEntries(d));
    s = sumNutri(all);
    s.total = s.total.map(x => days.length ? x / days.length : 0);
    title = '直近7日の平均'; sub = `記録のある${days.length}日の平均です`;
  } else {
    s = sumNutri(dayEntries(viewDate));
    title = `${dateLabel(viewDate)}の栄養素`; sub = '1日の合計です';
  }
  nutriCtx = { mode };
  const rows = kind => NUTRI.map((x, i) => x[4] === kind ? nutriRow(i, s.total[i], s.unknown[i], p, mode === 'week' ? 'week' : 'day') : '').join('');
  openSheet(esc(title), `
    <div class="small muted">${esc(sub)}。食事摂取基準（2025年版）の値と並べています</div>
    <div class="gu-head">ミネラル・食物繊維</div><div class="ngrid">${rows('main')}</div>
    <div class="gu-head">ビタミン</div><div class="ngrid">${rows('vit')}</div>
    <div class="note">食品成分表の値から計算した目安です。ゆでる・煮るなどで減る分（水に溶けるビタミンなど）は計算に入っていないので、実際より多めに出ます。栄養素をタップすると、どの食べ物から何をとったかが見られます。</div>
  `, null, { tall: true });
}
/* --- 記録の編集 --- */
function openEdit(id) {
  const e = dayEntries(viewDate).find(x => x.id === id);
  if (!e) return;
  if (e.code && foodByCode.has(e.code)) {
    sheetCtx = null;
    openAmount(e.code, { entry: e });
  } else if (e.perUnit != null) {
    openItemAmount(itemFromEntry(e), e);
  }
}

/* --- 履歴・マイリストから1タップで記録 --- */
function addFromHistory(i) {
  const src = sheetCtx.hist && sheetCtx.hist[i];
  if (!src) return;
  const c = Object.assign({}, src, { meal: sheetCtx.meal });
  delete c.id;
  addEntry(viewDate, c);
  toast(`${c.name} ${fmt(c.protein)}g を${mealLabel(c.meal)}に記録しました`);
  render();
}
function addFromMl(id) {
  const it = state.myList.find(x => x.id === id);
  if (!it) return;
  if (it.kind !== 'prod' && it.kind !== 'menu' && !foodsReady) { toast('食品データを読み込み中です'); return; }
  const e = mlEntry(it, sheetCtx.meal);
  if (!e) return;
  addEntry(viewDate, e);
  toast(`${e.name} ${fmt(e.protein)}g を${mealLabel(e.meal)}に記録しました`);
  render();
  renderResults();
}
function adjustMl(id) {
  const it = state.myList.find(x => x.id === id);
  if (!it) return;
  if (it.kind === 'food') {
    openAmount(it.code, { preset: it, mlId: it.id, label: it.name });
  } else if (it.kind === 'dish' || it.kind === 'gen') {
    const item = mlItemFull(it);
    if (!item) { toast('食品データを読み込み中です'); return; }
    openItemAmount(Object.assign({}, item, { name: it.name }), null, it.qty, it.id);
  } else {
    openItemAmount(mlItem(it), null, it.basis === '100g' ? (it.defGrams || 100) : 1, it.id);
  }
}

function downloadJson(obj, filename) {
  const blob = new Blob([JSON.stringify(obj, null, 1)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}

/* --- 前日コピー --- */
function copyPrevMeal(meal) {
  const prev = addDays(viewDate, -1);
  const src = dayEntries(prev).filter(e => e.meal === meal);
  if (!src.length) { toast(`前日の${mealLabel(meal)}の記録がありません`); return; }
  src.forEach(e => {
    const c = Object.assign({}, e);
    delete c.id;
    addEntry(viewDate, c);
  });
  toast(`前日の${mealLabel(meal)}（${src.length}件）をコピーしました`);
  render();
}

/* --- バックアップ --- */
function exportData() {
  downloadJson({ app: 'protein-note', version: 1, exportedAt: new Date().toISOString(), data: state }, `protein-note-backup-${todayStr()}.json`);
}
function importData(file) {
  const rd = new FileReader();
  rd.onload = () => {
    try {
      const obj = JSON.parse(rd.result);
      const d = obj && obj.app === 'protein-note' ? obj.data : null;
      if (!d || typeof d.days !== 'object') throw new Error('bad');
      if (!confirm('今のデータをバックアップの内容で置き換えます。よろしいですか？')) return;
      state = Object.assign(defaultState(), d);
      saveState();
      toast('復元しました');
      render();
    } catch (e) {
      toast('このファイルは読み込めませんでした');
    }
  };
  rd.readAsText(file);
}

/* =========================================================
   イベント
   ========================================================= */
/* 画面が切りかわるボタン（記録する・修正する・＋・完了）のあと少しの間は、続けて押されたタップを無視する
   （2回目のタップが、切りかわった先の画面のボタンを押してしまわないように） */
let tapLock = { t: 0, x: 0, y: 0 };
const TAP_LOCK_IDS = new Set(['saveAmt', 'saveMy']);
document.addEventListener('click', ev => {
  // 同じ場所をすぐにもう一度押したとき（2度押し）だけ無視する。別の場所のボタンはすぐ押せる
  if (Date.now() < tapLock.t && Math.hypot(ev.clientX - tapLock.x, ev.clientY - tapLock.y) < 40) { ev.preventDefault(); return; }
  const lb = ev.target.closest('button');
  if (lb && (TAP_LOCK_IDS.has(lb.id) || lb.dataset.madd || lb.dataset.mfinish)) tapLock = { t: Date.now() + 400, x: ev.clientX, y: ev.clientY };
  const b = ev.target.closest('button, [data-close]');
  if (!b) {
    if (ev.target.id === 'sheetBackdrop') closeOrBack();
    if (ev.target.id === 'photoViewer') closePhotoViewer();
    return;
  }
  const ds = b.dataset;

  if (ds.hop) { hopMedaka(b.querySelector('img')); return; }
  if (ds.tab) { switchTab(ds.tab); return; }
  if (ds.go) { switchTab(ds.go); return; }
  if (ds.close) { closeOrBack(); return; }
  if (ds.multi) { openMulti(sheetCtx && sheetCtx.meal || guessMeal()); return; }
  if (ds.mrow) { readMultiInputs(); multiCtx.terms.push(''); const box = $('#mInputs'); box.insertAdjacentHTML('beforeend', multiInputRow('', multiCtx.terms.length - 1)); box.lastElementChild.focus(); return; }
  if (ds.madd) { if (!multiCtx.done[ds.madd]) multiAdd(ds.madd); return; }
  if (ds.mpick) { multiPick(ds.mpick); return; }
  if (ds.mmore) { multiSaveScroll(); multiCtx.open[ds.mmore] = true; openMultiResults(); return; }
  if (ds.medit) { multiCtx.returnTo = false; openMultiInput(); return; }
  if (ds.mfinish) { multiCtx.pending = null; sheetCtx = { multi: 'results' }; closeOrBack(); return; }
  if (ds.add) { openAdd(ds.add); return; }
  if (ds.copy) { copyPrevMeal(ds.copy); return; }
  if (ds.edit) { openEdit(ds.edit); return; }
  if (ds.quick) { sheetCtx = { meal: guessMeal() }; openAmount(ds.quick); return; }
  if (ds.photo) { openPhotoViewer(ds.photo); return; }
  if (ds.pmove) { movePhoto(ds.pmove); return; }
  if (ds.day) { viewDate = ds.day; switchTab('today'); return; }
  if (ds.wdel) {
    if (confirm(`${dateLabel(ds.wdel)}の体重の記録を削除しますか？`)) { state.weights = (state.weights || []).filter(x => x.d !== ds.wdel); saveState(); render(); }
    return;
  }
  if (ds.pick) { openAmount(ds.pick); return; }
  if (ds.hist) { addFromHistory(Number(ds.hist)); return; }
  if (ds.mlrec) { addFromMl(ds.mlrec); return; }
  if (sheetCtx && sheetCtx.item && sheetCtx.item.sel && (ds.gu || ds.dashi || ds.gued || ds.gug || ds.gupc || ds.gulv)) { // 具を選べる料理
    const it = sheetCtx.item;
    const d = DISHES.find(x => x.id === it.id);
    const v = Number(sheetCtx.val) || 1;
    if (ds.gu) {
      const on = it.sel.includes(ds.gu);
      it.sel = on ? it.sel.filter(k => k !== ds.gu) : it.sel.concat(ds.gu);
      if (on && sheetCtx.guEdit === ds.gu) sheetCtx.guEdit = null;
    } else if (ds.dashi) it.dashi = ds.dashi;
    else if (ds.gued) sheetCtx.guEdit = sheetCtx.guEdit === ds.gued ? null : ds.gued;
    else {
      const g = d.gu.find(x => x[0] === sheetCtx.guEdit);
      if (!g) return;
      const sp = guSpec(g);
      let a;
      if (ds.gulv) a = Number(ds.gulv);
      else if (ds.gug) a = Number(ds.gug) / v;
      else { // 個数の ＋・−（見えている個数で1つずつ。1より少ないときは 0.5 刻み）
        const shown = r1(guAmt(g, it.ga) * v);
        const next = Number(ds.gupc) > 0 ? (shown < 1 ? shown + 0.5 : Math.floor(shown) + 1) : (shown <= 1 ? 0.5 : Math.ceil(shown) - 1);
        a = Math.max(0.5, next) / v;
        if (sp.t !== 'pc') return;
      }
      it.ga = Object.assign({}, it.ga, { [g[0]]: a });
    }
    guRecalc(true);
    return;
  }
  if (ds.dishpick) { const d = DISHES.find(x => x.id === ds.dishpick); const it = d && dishItem(d); if (it) openItemAmount(it, null, dishDefVal(d)); return; }
  if (ds.genpick) { const g = GENERIC_ITEMS.find(x => x.id === ds.genpick); if (g) openItemAmount(g, null, (state.recent['gen:' + g.id] || {}).v || g.defVal); return; }
  if (ds.nutri) { openNutriSheet(ds.nutri); return; }
  if (ds.nbd != null) { const fromSheet = !!b.closest('#sheet'); if (!fromSheet) nutriCtx = null; openNutriBreakdown(Number(ds.nbd), ds.nbm); if (fromSheet) nutriCtx.back = true; return; }
  if (ds.web) { openWebSearch(ds.web); return; }
  if (ds.newsx) { markNewsSeen(); render(); return; }
  if (ds.newsgo) {
    markNewsSeen();
    switchTab(NEWS[0].go || 'settings');
    const el = $('#dispCard'); if (el) setTimeout(() => el.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
    return;
  }
  if (ds.regpick) { regPick(Number(ds.regpick)); return; }
  if (ds.mladj) { adjustMl(ds.mladj); return; }
  if (ds.mlnew) {
    const fromAdd = sheetCtx && sheetCtx.meal && !sheetCtx.code && !sheetCtx.item ? sheetCtx.meal : null;
    openMlForm(null, { name: ds.mlnew !== '1' ? ds.mlnew : '', meal: fromAdd });
    return;
  }
  if (ds.mledit) { sheetCtx = null; openMlForm(ds.mledit); return; }
  if (ds.mode) { sheetCtx.mode = ds.mode; if (multiCtx) multiCtx.mode = ds.mode; setSeg(ds.mode); renderResults(); return; }
  if (ds.meal && sheetCtx) {
    sheetCtx.meal = ds.meal;
    document.querySelectorAll('.meal-pick .chip').forEach(c => c.classList.toggle('on', c.dataset.meal === ds.meal));
    return;
  }
  if (ds.amode && sheetCtx && sheetCtx.code) {
    // 切り替えても重さを引き継ぐ
    const g = currentGrams();
    const f = foodByCode.get(sheetCtx.code);
    sheetCtx.amode = ds.amode;
    if (ds.amode === 'g') {
      const mr = isDrink(f) ? mlRate(f) : null;
      if (mr) { sheetCtx.unit = 'mL'; sheetCtx.value = g ? r1(g * 100 / mr.r) : 200; }
      else { sheetCtx.unit = 'g'; sheetCtx.value = g || amountSet(foodByCode.get(sheetCtx.code)).def; }
    }
    if (ds.amode === 'raw' && f.rate && g) sheetCtx.raw = r1(g * 100 / f.rate);
    renderAmountBody();
    return;
  }
  if (ds.uidx && sheetCtx && sheetCtx.code) { sheetCtx.unitIdx = Number(ds.uidx); renderAmountBody(); return; }
  if (ds.cnt && sheetCtx && sheetCtx.code) {
    sheetCtx.count = Math.max(0.5, r1(sheetCtx.count + Number(ds.cnt)));
    $('#cntVal').textContent = fmt(sheetCtx.count);
    updAmount();
    return;
  }
  if (ds.rawg && sheetCtx && sheetCtx.code) { sheetCtx.raw = Number(ds.rawg); $('#rawAmt').value = ds.rawg; updAmount(); return; }
  if (ds.unit && sheetCtx && sheetCtx.code) {
    const f = foodByCode.get(sheetCtx.code);
    if (ds.unit === sheetCtx.unit) return;
    const grams = currentGrams();
    sheetCtx.unit = ds.unit;
    const mr = mlRate(f);
    sheetCtx.value = ds.unit === 'mL' && mr ? r1(grams * 100 / mr.r) : grams;
    renderAmountBody();
    return;
  }
  if (ds.g && sheetCtx && sheetCtx.code) {
    sheetCtx.value = Number(ds.g);
    $('#amt').value = ds.g;
    updAmount();
    return;
  }
  if (ds.q && sheetCtx && sheetCtx.item) {
    sheetCtx.val = Number(ds.q);
    $('#qty').value = ds.q;
    $('#qty').dispatchEvent(new Event('input'));
    return;
  }

  switch (b.id) {
    case 'prevDay': viewDate = addDays(viewDate, -1); render(); break;
    case 'nextDay': viewDate = addDays(viewDate, 1); render(); break;
    case 'dateLabel': viewDate = todayStr(); render(); break;
    case 'pastTodayBtn':
    case 'todayBtn': viewDate = todayStr(); render(); window.scrollTo(0, 0); break;
    case 'mGo': runMulti(); break;
    case 'saveAmt': {
      if (sheetCtx.reg) { if (starCurrentFood()) finishReg(); break; }
      const data = foodEntryData(sheetCtx, sheetCtx.meal);
      if (!data) return;
      if (sheetCtx.editing) { updateEntry(viewDate, sheetCtx.editing.id, data); toast('修正しました'); }
      else { addEntry(viewDate, data); if (!(multiCtx && multiCtx.returnTo)) toast(`${data.name} ${fmt(data.protein)}g を記録しました`); }
      afterSave(data);
      break;
    }
    case 'saveMy': {
      const it = sheetCtx.item;
      const v = Number(sheetCtx.val);
      if (!(v > 0)) return;
      const data = itemEntryData(it, v, sheetCtx.meal, sheetCtx.mlId);
      if (sheetCtx.editing) { updateEntry(viewDate, sheetCtx.editing.id, data); toast('修正しました'); }
      else { addEntry(viewDate, data); if (!(multiCtx && multiCtx.returnTo)) toast(`${it.name} ${fmt(data.protein)}g を記録しました`); }
      afterSave(data);
      break;
    }
    case 'delEntry':
      if (sheetCtx && sheetCtx.editing && confirm('この記録を削除しますか？')) {
        removeEntry(viewDate, sheetCtx.editing.id); closeSheet(); render();
      }
      break;
    case 'wSave': saveWeight(); break;
    case 'exportBtn': exportData(); break;
    case 'importBtn': $('#importFile').click(); break;
    case 'starBtn': starCurrentFood(); break;
    case 'starItem': starCurrentItem(); break;
    case 'regItem': if (starCurrentItem()) finishReg(); break;
    case 'saveMlItem': saveMlItem(); break;
    case 'regGo': runRegSearch(); break;
    case 'regNum': openMlForm(null, { kind: 'menu' }); break;
    case 'mlRegMenu': openMlSearch(); break;
    case 'photoAddBtn': $('#photoInput').click(); break;
    case 'pvDelete': deleteViewedPhoto(); break;
    case 'pvClose': closePhotoViewer(); break;
    case 'wipeBtn':
      if (confirm('すべての記録・設定・マイ食品を削除します。元に戻せません。よろしいですか？')) {
        state = defaultState(); saveState(); deleteAllPhotos().then(render); toast('削除しました');
      }
      break;
  }
});

document.addEventListener('change', ev => {
  if (ev.target.id === 'photoInput' && ev.target.files.length) { addPhotos(Array.from(ev.target.files)); ev.target.value = ''; }
  if (ev.target.id === 'showNutri') { state.showNutri = ev.target.checked; saveState(); if (state.showNutri) loadNutri(); toast(state.showNutri ? 'ほかの栄養素を表示します' : 'ほかの栄養素を隠しました'); render(); return; }
  if (ev.target.id === 'showPFC') { state.showPFC = ev.target.checked; saveState(); toast(state.showPFC ? 'カロリー・PFCを表示します' : 'カロリー・PFCを隠しました'); return; }
  if (ev.target.id === 'keepDays') { state.photoKeepDays = Number(ev.target.value); saveState(); cleanupPhotos(); toast('保存しました'); }
  if (ev.target.id === 'importFile' && ev.target.files[0]) importData(ev.target.files[0]);
  if (ev.target.name === 'sex') $('#statusField').hidden = ev.target.value !== 'f';
});
document.addEventListener('submit', ev => {
  if (ev.target.id !== 'profileForm') return;
  ev.preventDefault();
  const fd = new FormData(ev.target);
  const sex = fd.get('sex');
  // 体重の入力ミス（年齢を入れてしまう等）を確認
  const ageV = Number(fd.get('age')), wV = fd.get('weight') ? Number(fd.get('weight')) : 0;
  const warn = $('#weightWarn');
  let why = '';
  if (wV && wV === ageV) why = `体重が年齢と同じ「${wV}」になっています。`;
  else if (wV && ageV >= 18 && wV < 30) why = `体重${wV}kgは、大人としてはかなり軽い値です。`;
  if (why && ev.target.dataset.weightOk !== String(wV)) {
    ev.target.dataset.weightOk = String(wV);
    if (warn) { warn.textContent = why + ' 体重（kg）で合っていれば、もう一度「保存」を押してください。'; warn.hidden = false; }
    $('#weight').focus();
    return;
  }
  if (warn) warn.hidden = true;
  state.profile = {
    age: Number(fd.get('age')),
    sex,
    weight: fd.get('weight') ? Number(fd.get('weight')) : null,
    height: fd.get('height') ? Number(fd.get('height')) : null,
    status: sex === 'f' ? (fd.get('status') || 'none') : 'none',
    activity: fd.get('activity') || (state.profile && state.profile.activity) || 'mid',
  };
  saveState();
  toast('保存しました');
  switchTab('today');
});
document.addEventListener('keydown', ev => {
  if (ev.key !== 'Escape') return;
  if (!$('#photoViewer').hidden) closePhotoViewer(); else if (!$('#sheet').hidden) closeOrBack();
});

function switchTab(tab) {
  currentTab = tab;
  document.querySelectorAll('.tab').forEach(s => { s.hidden = s.id !== 'tab-' + tab; });
  document.querySelectorAll('.tabbar button').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
  window.scrollTo(0, 0);
  render();
}

/* ---------- 起動 ---------- */
if (!state.profile) currentTab = 'today';
if (!state.profile && !Object.keys(state.days).length && NEWS[0]) state.newsSeen = NEWS[0].id; // はじめて使う人にはお知らせを出さない（保存は最初の操作のときでよい）
render();
loadFoods();
if (state.showNutri) loadNutri();
cleanupPhotos();
if ('serviceWorker' in navigator && location.protocol !== 'file:') {
  // 新しい版が入ったら自動で読み込み直す（入力中のシートが開いていたら次回起動に回す）
  const hadController = !!navigator.serviceWorker.controller;
  let reloaded = false;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!hadController || reloaded) return;
    const sheet = document.getElementById('sheet');
    if (sheet && !sheet.hidden) return;
    reloaded = true;
    location.reload();
  });
  window.addEventListener('load', () => navigator.serviceWorker.register('sw.js').catch(() => {}));
}
